MultiLanguageItemData['mx'][200120] = {name = "[q4]Núcleo de poder de Irideus", additional_info = "Objeto de misión\n[q2]Uso: Armoniza el núcleo de poder con un habitante de élite titánico de Fuerte Tyr y lo debilita.\n[q]\"Tomado de las Salas de Infusión, este dispositivo alguna vez potenció al Vigía Irideus. Ahora debe armonizarse nuevamente para recuperar su generación de energía original.\""}
