MultiLanguageItemData['mx'][200549] = {name = "[q3]Artefacto titánico restaurado", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+244 intelecto\n[q2]Uso: Escudas a un aliado a una distancia de hasta 37740 p. y aumentas hasta 5726 p. la velocidad. Los montos de absorción y velocidad dependen de la distancia que te separe de tu objetivo. La absorción aumenta con la cercanía y la velocidad se reduce. (1 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][200550] = {name = "[q3]Piel muy cómoda", additional_info = "Se liga al recogerlo\nJuguete\n[q2]Uso: ¡Ponte cómodo al mejor estilo maruuk! (20 Min Reutilización)\nRequiere reconocimiento 3 con los Centauros Maruuk y que hayas completado la misión \"Intercambio cultural\".\nPrecio de venta:"}
MultiLanguageItemData['mx'][200551] = {name = "[q3]Pilón de pieles cómodas", additional_info = "Se liga al recogerlo\nJuguete\n[q2]Uso: ¡Descansa como una khanam adondequiera que vayas! (20 Min Reutilización)\nRequiere reconocimiento 3 con los Centauros Maruuk y que hayas completado la misión \"Intercambio cultural\".\nPrecio de venta:"}
MultiLanguageItemData['mx'][200552] = {name = "[q3]Caparazón del clamatorrentes", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+244 fuerza\n[q2]Uso: Canaliza torrentes a tu alrededor que infligen [ 1906 * (6) * (1 + Versatilidad)] p. de daño de naturaleza a los jugadores cercanos durante 3 s. Luego desata una explosión poderosa que inflige 53355 p. de daño de naturaleza divididos entre todos los enemigos cercanos. (2 Min, 30 Seg Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][200553] = {name = "Néctar de panthis", additional_info = "Suministros de las Islas Dragón\nSe liga al recogerlo\n[q2]Agrega el néctar de panthis a tus suministros de las Islas Dragón.\n[q]\"La flor en forma de cuenco crea un estanque donde el néctar se acumula. Con alto contenido de azúcares, el néctar refinado es muy codiciado en la cocina.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][200554] = {name = "Cabeza de hongo caído", additional_info = "Suministros de las Islas Dragón\nSe liga al recogerlo\n[q2]Agrega la cabeza de hongo caído aceitoso a tus suministros de las Islas Dragón.\n[q]\"El hongo caído produce un aceite cuando madura y es muy buscado como agente acelerador de combustión.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][200555] = {name = "Semillas infernales", additional_info = "Suministros de las Islas Dragón\nSe liga al recogerlo\n[q2]Agrega las semillas infernales a tus suministros de las Islas Dragón.\n[q]\"Similares a la pólvora, las vainas infernales explotan cuando maduran por completo y diseminan las semillas. Los djaradin las reúnen justo cuando están por florecer y las usan para elevar la temperatura de sus forjas casi a punto de fusión.\"\nPrecio de venta:"}
