MultiLanguageItemData['mx'][200884] = {name = "[q3]Conjunto: Cota de malla de dracoequitador glorioso", additional_info = "[q7]Se liga a la tropa\nClases: Cazador , Chamán , [Evoker]\n[q2]Uso: Reúne las apariencias del conjunto de armadura Cota de malla de dracoequitador glorioso.\n[q]\"Los detalles dorados y carmesí marcan a un drekirjar como una fuerza imparable.\""}
MultiLanguageItemData['mx'][200885] = {name = "Té de flor de ceniza y canela", additional_info = "Se liga al recogerlo\nÚnico (20)\n[q2]Uso: Esta infusión de pétalos de flores chispeantes de Hyjal es un gran energizante. Aumenta la velocidad de movimiento un 30% durante 1 h.\n\n Solo se activa cuando estás en las Islas Dragón.\nPrecio de venta:"}
MultiLanguageItemData['mx'][200886] = {name = "Té de hojaplata y limón", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Siéntete remilgado y a gusto con esta infusión clásica de los Reinos del Este.\nPrecio de venta:"}
MultiLanguageItemData['mx'][200887] = {name = "Porter asada", additional_info = "Se liga al recogerlo\nÚnico (20)\n[q2]Uso: Una jarra de porter asada bendecida por los loa para acompañar platillos de carne. Aumenta tu [Primary Stat] un 10% durante 1 h.\n\n Solo se activa cuando estás en las Islas Dragón.\nPrecio de venta:"}
MultiLanguageItemData['mx'][200888] = {name = "Costillar al carbón", additional_info = "Se liga al recogerlo\nÚnico (20)\n[q2]Uso: Costillas asadas sobre un colchón de hierba ancla, polen de sirena y carbón vorquin fresco. ¡Con el primer bocado, su intenso sabor corre por tus venas! Aumenta el aguante un 20% durante 1 h.\n\n Solo se activa cuando estás en las Islas Dragón.\nPrecio de venta:"}
MultiLanguageItemData['mx'][200889] = {name = "Anca extrasazonada", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: ¡Te llena la panza con una deliciosa anca de cuernoatroz adobada con una generosa cantidad de mordedura de Akunda! ¡De repente sientes el poder de un gran guerrero!\nPrecio de venta:"}
MultiLanguageItemData['mx'][200890] = {name = "Brocheta de cosecha del Espolón", additional_info = "Se liga al recogerlo\nÚnico (20)\n[q2]Uso: Una brocheta de vegetales condimentados y levemente asados, cosecha de las granjas Pezuña de Sangre de Kalimdor. Aumenta la regeneración de maná un 30% durante 1 h.\n\n Solo se activa cuando estás en las Islas Dragón.\nPrecio de venta:"}
MultiLanguageItemData['mx'][200891] = {name = "Ensalada soñada druídica", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Bayas de Amparo de la Noche sobre un colchón de verdes que alivian el espíritu, ¡para que sientas la gloria de la vida que crece en todo momento y en todo lugar!\nPrecio de venta:"}
MultiLanguageItemData['mx'][200892] = {name = "Ponche de fruta del dragón", additional_info = "Se liga al recogerlo\nÚnico (20)\n[q2]Uso: Relájate con una copa de las frutas y bayas más finas de las Islas Dragón de este lado de las Cascadas. Reduce la velocidad de caída.\n\n Solo se activa cuando estás en las Islas Dragón.\nPrecio de venta:"}
MultiLanguageItemData['mx'][200893] = {name = "Langosta escalfada a la azsuniana", additional_info = "Se liga al recogerlo\nÚnico (20)\n[q2]Uso: Langosta de Nor'danil en salmuera escalfada con el método tradicional de las Islas Quebradas. Aumenta todas las estadísticas un 5% durante 1 h.\n\n Solo se activa cuando estás en las Islas Dragón.\nPrecio de venta:"}
MultiLanguageItemData['mx'][200894] = {name = "Arcavino añejo raro", additional_info = "Se liga al recogerlo\nÚnico (20)\n[q2]Uso: Las notas dulces y tánicas de este arcavino evocan Suramar y agudizan tus sentidos. Aumenta el daño crítico un 30% durante 1 h.\n\n Solo se activa cuando estás en las Islas Dragón.\nPrecio de venta:"}
MultiLanguageItemData['mx'][200895] = {name = "Bandeja de quesos taladorianos finos", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: ¡El aire se llena del maravilloso aroma de un surtido de quesos añejos de sabor intenso, elaborados con leche de talbuks, uñagrietas y elekks alimentados con orquídeas de granjas draenei!\nPrecio de venta:"}
MultiLanguageItemData['mx'][200896] = {name = "Siluro caramelizado del capitán", additional_info = "Se liga al recogerlo\nÚnico (20)\n[q2]Uso: Siluro de Puerto del Puente cocinado a punto crujiente, digno de un Valiente. Aumenta la armadura un 30% durante 1 h.\n\n Solo se activa cuando estás en las Islas Dragón.\nPrecio de venta:"}
MultiLanguageItemData['mx'][200897] = {name = "Leche de cabra de Venrik", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Incluso sin la tradicional jarra de calavera, ¡te sientes como todo un pirata de Puerto Libre!\nPrecio de venta:"}
MultiLanguageItemData['mx'][200898] = {name = "Cóctel de gamba mantis", additional_info = "Se liga al recogerlo\nÚnico (20)\n[q2]Uso: Gamba de mantis en salmuera con limón de Aldea Binan remojada en salsa bocardiente agria. Otorga respiración acuática.\n\n Solo se activa cuando estás en las Islas Dragón.\nPrecio de venta:"}
MultiLanguageItemData['mx'][200899] = {name = "Fideos de niebla marina asados", additional_info = "Se liga al recogerlo\nÚnico (20)\n[q2]Uso: Fideos de niebla marina calientes directo de la sartén, con raíces y vegetales de Zarpa'don cortados en cubos pequeños y bonitos. Aumenta la celeridad un 10% durante 1 h.\n\n Solo se activa cuando estás en las Islas Dragón.\nPrecio de venta:"}
MultiLanguageItemData['mx'][200900] = {name = "Burrito de emperador frito", additional_info = "Se liga al recogerlo\nÚnico (20)\n[q2]Uso: Salmón emperador crujiente freído en aceites pandaren y condimentado con especias, envuelto en una tortilla de harina zandalari recién molida. Aumenta un 20% la maestría durante 1 h.\n\n Solo se activa cuando estás en las Islas Dragón.\nPrecio de venta:"}
MultiLanguageItemData['mx'][200901] = {name = "Pimientos rellenos con queso roquefort", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Pimientos de Krasarang picantes con queso roquefort añejo de las cabras de pastoreo de Villa del Lago.\nPrecio de venta:"}
MultiLanguageItemData['mx'][200902] = {name = "Delicia de panna cotta de ñipa", additional_info = "Se liga al recogerlo\nÚnico (20)\n[q2]Uso: Un postre dulce y suave hecho con miel y queso cocido de Mildenhall, bañado en jarabe de ñipa espeso. Aumenta el poder de ataque un 10% durante 1 h.\n\n Solo se activa cuando estás en las Islas Dragón.\nPrecio de venta:"}
MultiLanguageItemData['mx'][200903] = {name = "Espresso especial de Moira", additional_info = "Se liga al recogerlo\nÚnico (20)\n[q2]Uso: Un café elaborado con granos tostados sobre una llama de arrabio, mezclado con zarzamora y malta. ¡Con razón es la mezcla favorita de la reina regente! Aumenta la velocidad de ataque un 30% durante 1 h.\n\n Solo se activa cuando estás en las Islas Dragón.\nPrecio de venta:"}
MultiLanguageItemData['mx'][200904] = {name = "Pastel de poma picante", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Pomas de Kun-Lai mezcladas con azúcares picantes de las profundidades de Ciudad Forjatiniebla.\n\n ¡Una delicia!\nPrecio de venta:"}
