MultiLanguageItemData['mx'][202698] = {name = "La voz dragonante 4: La ley del más fuerte", additional_info = "Objeto de misión\n[q]\"Los dRagones nos han dominado porque son más fuertes y poderOsos que nosotros. PeRo juntos somos más numerosos Y fuertes que ellos. Si la ley del más fuerte manda en este mundo, entonces vamos a tener que luchar juntos para salir adelante. - Instigadora Belaphon\""}
MultiLanguageItemData['mx'][202699] = {name = "La voz dragonante 2: Cien siglos de abandono", additional_info = "Objeto de misión\n[q]\"Por cien años, nos dejaron solos y desamparados, mientras nosotros cuidábamos \"sus\" islas, proteGíamos \"sus\" ciudades y caminos y manteníamos la paz. Repitieron ese abandono noVenta y nueve veces más. ¿Deberíamos recibirlos con los brazos abiertos Y obedecerles como aNtes? - Instigadora Belaphon\""}
MultiLanguageItemData['mx'][202700] = {name = "La voz dragonante 3: Cien siglos de independencia", additional_info = "Objeto de misión\n[q]\"Los dragones regresaron con la buena esperanza de Que fuéramos lo que éramos, pero habíamos camBiado en esos cien siglos. Crecimos. Sus siervos antes Fuimos, pero ya no les servimos. Hemos elegido nuestro propio camino por diEz mil años y volveremos a hacerlo. - Instigadora Belaphon\""}
MultiLanguageItemData['mx'][202701] = {name = "La voz dragonante 5: El código rebelde", additional_info = "Objeto de misión\n[q]\"Y así juramos lealtad, todos y cada uno, al código rebelde. Ningún gobernante más Que uno mismo. Ningún pRopósito más que la autosuFiciencia. Ningún vuelo más que los Sinvuelo. - Instigadora Belaphon\""}
MultiLanguageItemData['mx'][202702] = {name = "La voz dragonante 1: El valor de los dragonantes", additional_info = "Objeto de misión\n[q]\"Los dragoNes creen que valen más que nosotros. Por eso Sendrax tuvo que sacrificarse, Por un huevo de dragón que quizá ni siquiera sea viable. Dicen que es una heroíNa, pero, en verdAd, es su víctima. - Instigadora Belaphon\""}
