MultiLanguageItemData['mx'][203385] = {name = "Runa de pirovisión", additional_info = "Objeto de misión\n[q]\"El tótem se apaga cuando quitas la runa. Parecen estar armonizados.\""}
MultiLanguageItemData['mx'][203386] = {name = "Caja de galletas brincamaizales", additional_info = "Objeto de misión\nÚnico\n[q]\"Una caja de galletas de la marca El Carnero Asado\""}
MultiLanguageItemData['mx'][203387] = {name = "Arma de entrenamiento extrañamente familiar", additional_info = "Objeto de misión\n[q]\"Tienes la certeza de que te deshiciste de ella hace años cuando necesitabas hacer más lugar en tus bolsas. Era tu vieja y confiable amiga.\""}
MultiLanguageItemData['mx'][203388] = {name = "Insignia asquerosa", additional_info = "Objeto de misión\n[q]\"El símbolo ya casi ni se ve, pero quizá para el Kirin Tor posea un interés histórico.\""}
MultiLanguageItemData['mx'][203389] = {name = "Roca brillante", additional_info = "Objeto de misión\n[q]\"Brilla, así que debe ser importante, ¡¿no?!\""}
MultiLanguageItemData['mx'][203390] = {name = "[q2]Anillo de vínculo elemental de Maldra", additional_info = "Objeto de misión\n[q2]Uso: Vincula a la instigadora Belaphon con la magia elemental de Maldra. Solo se puede utilizar en enemigos que tienen menos de un 50% de salud.\n[q]\"Maldra hechizó este anillo con el vínculo elemental que usaron contra ella en el Valle Neblinoso.\""}
MultiLanguageItemData['mx'][203391] = {name = "Reloj de bolsillo enano dañado", additional_info = "Objeto de misión\n[q]\"El grabado del dorso dice: \"Profesor Lichenrock\".\""}
