MultiLanguageItemData['mx'][203394] = {name = "Orbe con carga elemental", additional_info = "Objeto de misión\n[q]\"Un curioso artefacto con forma de orbe que parece tener origen titánico. Sin embargo, de su interior emana un haz de energía elemental.\""}
MultiLanguageItemData['mx'][203395] = {name = "Cuaderno de investigación", additional_info = "Objeto de misión\n[q]\"El diario está en increíbles condiciones a pesar de su antigüedad. Las notas que contiene sin duda mantendrán ocupados a los eruditos dragontina durante muchos años.\"\n[q2]<Click derecho para leer>"}
MultiLanguageItemData['mx'][203396] = {name = "Pieza de armadura expuesta", additional_info = "Objeto de misión\n[q]\"El diseño parece de los dragones negros, pero es más pequeña de lo esperado. ¿Será un ejemplo temprano de la armadura dracthyr?\""}
