MultiLanguageItemData['mx'][203408] = {name = "[q4]Tridente ceremonial antiguo", additional_info = "Curiosidades artesanales\n[q]\"Este tridente no está hecho de materiales aptos para el combate, parece tener características ritualistas. Ten cuidado cuando lo coloques en el Confín Prohibido. Puede activar un enfrentamiento especial.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][203409] = {name = "[q4]Faltriquera de especias resplandeciente", additional_info = "Curiosidades artesanales\n[q]\"¡El ingrediente que faltaba era amor! El aroma es sensacional. Esto es una muestra maravillosa del Confín Prohibido. Puede activar un enfrentamiento especial.\"\nPrecio de venta:"}
