MultiLanguageItemData['mx'][203413] = {name = "[q4]Diapasón armonizador para cristales", additional_info = "Curiosidades artesanales\n[q]\"Golpear el cristal indicado con esto en el Confín Prohibido podría producir una nota melodiosa. Puede activar un encuentro especial.\"\nPrecio de venta:"}
