MultiLanguageItemData['mx'][203416] = {name = "[q4]Semillas de flor de vida inertes", additional_info = "Curiosidades artesanales\n[q]\"Se recogen en el Confín Prohibido. El aroma de los brotes de esta flor especial atrae a los insectos de la región. Puede activar un encuentro especial.\"\nPrecio de venta:"}
