MultiLanguageItemData['mx'][203707] = {name = "Cubo de agua", additional_info = "Objeto de misión\nÚnico\n[q2]Uso: Arroja un cubo de agua para extinguir todos los fuegos en un radio de 3 m del área seleccionada.\n[q]\"Un cubo de agua fresca utilizado por los alfareros olfatopos.\""}
