MultiLanguageItemData['mx'][203710] = {name = "[q4]Llave de llama eterna", additional_info = "Se liga al recogerlo\nÚnico (3)\n[q]\"Una de varias llaves necesarias para abrir un cargamento protegido. Solo se confía a los mejores herreros de Igira. Se consume con el uso.\""}
