MultiLanguageItemData['mx'][203714] = {name = "[q4]Resguardo de ira ignota", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+487 [Agilidad o Fuerza o Intelecto]\n[q2]Uso: Otorga Resguardo agónico a un aliado durante 10 s, que absorbe un máximo de 177207 p. de daño. Si se destruye, el Resguardo se transforma en Ira agónica, que inflige [ 15193 * (1.15385)] p. de daño de pirosombra durante 6 s al último enemigo que lo golpee. (1 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][203715] = {name = "Oro supurante", additional_info = "Se liga al recogerlo\nÚnico (20)\nDuración: 2 h (tiempo real)\n[q2]Uso: Arrójalo para liberar el líquido viscoso dorado en el interior. (10 Seg Reutilización)\n[q]\"Es hermoso a la vista, pero difícil de gastar.\"\nPrecio de venta:"}
