MultiLanguageItemData['mx'][204356] = {name = "[q2]Polvo de gemas ilustre", additional_info = "Se liga al recogerlo\nMaterial de profesión\n[q]\"Lo obtienen los joyeros cuando pulverizan gemas reveladas por el Cataclismo. Se puede intercambiar por muestras de joyero ilustre en Ventormenta u Orgrimmar.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][204359] = {name = "[q3]Bolso de velocista del Confín", additional_info = "Se liga al recogerlo\n[q]\"Lleno de oro y suministros de las Islas Dragón y tal vez contenga un manuscrito de los vigías dracónicos.\"\n[q2]<Click derecho para abrir>"}
MultiLanguageItemData['mx'][204360] = {name = "[q3]Orbe petrificado extraño", additional_info = "Se liga al recogerlo\n[q2]Uso: Combina el orbe petrificado extraño y restos de escamas de dragón negro para revertir la petrificación.\n[q]\"Encerrado en las bóvedas durante miles de años, este objeto está completamente solidificado. Quizás una fuente poderosa de magia de la tierra sirva para restaurarlo.\""}
MultiLanguageItemData['mx'][204361] = {name = "[q4]Dracorreptante sinuoso", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Estos dracos se sienten a gusto en las profundidades de la tierra y en los confines del cielo.\"\nLogro:\nUn descubrimiento serpentino"}
MultiLanguageItemData['mx'][204363] = {name = "[q3]Huevo particularmente ordinario", additional_info = "Se liga al recogerlo\n[q2]Uso: Combina tu huevo particularmente ordinario y una gota de magia de dragón azul para encantarlo.\n[q]\"No parece haber nada único sobre este huevo. Tal vez pueda ser potenciado con algo que se encuentre en las bóvedas.\""}
MultiLanguageItemData['mx'][204364] = {name = "[q3]Huevo mágicamente alterado", additional_info = "Se liga al recogerlo\n[q2]Uso: Combina tu huevo mágicamente alterado con algunos carbones rubí siempreardientes para que eclosione.\n[q]\"Un huevo que ha sido potenciado con misteriosa magia de dragones azules. Si tan solo encontraras algo en las bóvedas que sirviera para que haga eclosión.\""}
MultiLanguageItemData['mx'][204365] = {name = "Puñado de lanzas de ébano", additional_info = "Objeto de misión\n[q2]Uso: Clava una lanza de ébano en el cadáver de un djaradin zaqali. (5 Seg Reutilización)\n[q]\"Una colección de lanzas empuñadas por el Vuelo Negro. Siguen tan afiladas como el día que se forjaron.\""}
MultiLanguageItemData['mx'][204366] = {name = "[q3]Huevo de contenidos desconocidos", additional_info = "Se liga al recogerlo\n[q2]Uso: Combina tu huevo de contenidos desconocidos y una mota de polvo bronce para añejar tu huevo.\n[q]\"El huevo misterioso al fin se ha abierto, pero no logras distinguir cuál es la criatura que hay en su interior. Quizá se vea mejor cuando crezca. Debe haber algo en la bóveda que acelere el proceso.\""}
MultiLanguageItemData['mx'][204367] = {name = "[q3]Mamut antiguo durmiente", additional_info = "Se liga al recogerlo\n[q2]Uso: Combina tu mamut antiguo durmiente con un broche de dragón esmeralda para despertarlo.\n[q]\"¿Tu huevo alterado dio origen a un mamut? Eso no se ve bien, pero ahora no tiene caso detenerse. ¡Busca una forma de despertarlo y reclama tu premio!\""}
MultiLanguageItemData['mx'][204369] = {name = "[q3]Restos de escamas de dragón negro", additional_info = "Se liga al recogerlo\n[q2]Uso: Combina el orbe petrificado extraño y restos de escamas de dragón negro para revertir la petrificación.\n[q]\"Un destello de magia de la tierra aún persiste en estas escamas de dragón negro mudadas. Quizá sea capaz de revertir petrificaciones menores.\""}
MultiLanguageItemData['mx'][204370] = {name = "Poción brillante apestosa", additional_info = "Tóxico\n[q2]Uso: Ilumina el mundo a tu alrededor.\n[q]\"Mezclar dos partes de saxifraga molida, una de descomposición pura y arrojar unas esporas misteriosas para que el consumidor se mantenga alerta.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][204371] = {name = "[q3]Gota de magia de dragón azul", additional_info = "Se liga al recogerlo\n[q2]Uso: Combina tu huevo particularmente ordinario y una gota de magia de dragón azul para encantarlo.\n[q]\"Es difícil distinguir la imagen en el vial, pero no tienes duda de que es un dragón. Deberían considerar la posibilidad de volver a etiquetar estas cosas.\""}
MultiLanguageItemData['mx'][204372] = {name = "[q3]Mota de polvo bronce", additional_info = "Se liga al recogerlo\n[q2]Uso: Combina tu huevo de contenidos desconocidos y una mota de polvo bronce para añejar tu huevo.\n[q]\"Nadie ocultaría polvo en una bóveda del tesoro. Debe ser un catalizador poderoso de los dragones bronce para la magia del tiempo. Pero cuidado: ¡no uses demasiado!\""}
MultiLanguageItemData['mx'][204373] = {name = "[q3]Lámina de Rumble en mal estado", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Déjalo bien aplanado.\n[q]\"Déjalo bien aplanado.\""}
MultiLanguageItemData['mx'][204374] = {name = "[q3]Broche de dragón esmeralda", additional_info = "Se liga al recogerlo\n[q2]Uso: Combina tu mamut antiguo durmiente con un broche de dragón esmeralda para despertarlo.\n[q]\"Aunque está agrietado, sientes el poder del Sueño Esmeralda en su interior. Esto debería despertar a cualquier criatura.\""}
MultiLanguageItemData['mx'][204375] = {name = "[q3]Carbones rubí siempreardientes", additional_info = "Se liga al recogerlo\n[q2]Uso: Combina tu huevo mágicamente alterado con algunos carbones rubí siempreardientes para que eclosione.\n[q]\"Un puñado de carbones cálidos. Debe ser de las llamas sanadoras de un dragón rojo antiguo. Quizá sirva para infundir vida en algo pequeño.\""}
