MultiLanguageItemData['mx'][205204] = {name = "[q4]Alaesquisto llameante Sujeto 01", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar una montura Alaesquisto catalogada.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"La primera vez que se descubre un alaesquisto llameante. Nueve de cada diez investigadores coinciden: ¡está caliente!\"\nZona:\nCaverna Zaralek\nEvento público:\nInvestigadores bajo fuego"}
MultiLanguageItemData['mx'][205205] = {name = "[q4]Alaesquisto de la llama de las sombras", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Nacido del magma, su caparazón era originalmente una masa fundida que se enfrió hasta formar una roca volcánica de color oscuro. Estar imbuido de la llama de las sombras no ha hecho más que consolidar su naturaleza irrompible.\"\nLogro:\nGloria del asaltante de Aberrus"}
MultiLanguageItemData['mx'][205207] = {name = "[q4]Riendas de rastreador de bocados", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiere reconocimiento 18 con los Olfatopos de Loamm.\n\n\n[q]\"Una raza de alaesquistos entrenados por los olfatopos para encontrar los bocados más ocultos en las profundidades.\"\nVendedor:\nHarlowe Marl\nZona:\nCavernaZaralek\nCosto:\n800"}
MultiLanguageItemData['mx'][205208] = {name = "[q4]Alaesquisto arenoso", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nYa conocido\n\n\n[q]\"El diseño de las alas de esta criatura se asemeja a la arena que fluye por un reloj de arena. Uno se podría quedar contemplándolas eternamente...\"\nVendedor:\nCualquier vendedor de cronoviajes\nCosto:\n5000"}
MultiLanguageItemData['mx'][205209] = {name = "[q4]Riendas de transportista de piedras", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Se ha entrenado especialmente a estos alaesquistos para transportar grandes cantidades de piedras de intercambio para las actividades de regateo de los olfatopos.\"\nVendedor:\nPonzo\nZona:\nCaverna Zaralek\nCosto:\n85"}
