MultiLanguageItemData['mx'][206346] = {name = "[q4]Diario de Eva", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Realiza un ritual.\n[q]\"Un recuento detallado de sucesos cada vez más horrorosos. Quedan muchas páginas en blanco.\""}
MultiLanguageItemData['mx'][206347] = {name = "[q3]Talismán de maniquí", additional_info = "Se liga al recogerlo\nJuguete\n[q2]Uso: Transforma al taumaturgo en un maniquí del Puesto de venta. (10 Min Reutilización)\n[q]\"Representa el Puesto de venta.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][206348] = {name = "Llama fragmentada", additional_info = "Se liga al recogerlo\n[q2]Uso: Combina 5 llamas fragmentadas para crear un componente fragmentado o un fragmento de llamas.\n[q]\"Los restos destrozados de un fragmento de llamas robado en un ataque reciente.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][206349] = {name = "Componente fragmentado", additional_info = "Objeto de misión\nÚnico\n[q]\"¡Llamas fragmentadas fusionadas para crear algo nuevo!\""}
MultiLanguageItemData['mx'][206350] = {name = "[q3]Remanente radiante", additional_info = "Se liga al recogerlo\nRequiere reconocimiento 23 con los Arathi de Cristalia.\nRequiere reconocimiento 25 con los Arathi de Cristalia.\n[q]\"Un componente valioso que se usa como combustible para la luz de las magnaflamas.\""}
MultiLanguageItemData['mx'][206351] = {name = "[q3]Diseño: Campeón de veraplata", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a hacer un Campeón de veraplata.\nRequiere Herrería clásica (300)\nPrecio de venta:\n[q3]Campeón de veraplata\nSe liga al equiparlo\n{Dos manos} {Espada}\n{6 - 11 p. de daño} {Velocidad 3.60}\n(2.4 p. de daño por segundo)\nDurabilidad 100 / 100\n[q2]Probabilidad al acertar: Protege al taumaturgo con un Escudo Sagrado.\nPrecio de venta:\nRequiere Barra de mitril (30), Barra de veraplata (16), Rubí estrella (6), Aliento de viento (4), Piedra de pulir sólida (8), Cuero grueso (6)\n Componentes opcionales: [] (#49)"}
MultiLanguageItemData['mx'][206352] = {name = "[q3]Diseño: El Despedazador", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a hacer El Despedazador.\nRequiere Herrería clásica (300)\nPrecio de venta:\n[q3]El Despedazador\nSe liga al equiparlo\n{Una mano} {Maza}\n{4 - 5 p. de daño} {Velocidad 2.60}\n(1.7 p. de daño por segundo)\n+2 fuerza\n+2 aguante\nDurabilidad 90 / 90\nPrecio de venta:\nRequiere Barra de mitril (24), Núcleo de tierra (4), Barra de veraplata (6), Citrino (5), Jade (5), Piedra de pulir sólida (4), Cuero grueso (4)\n Componentes opcionales: [] (#31)"}
MultiLanguageItemData['mx'][206353] = {name = "Silbato de centinela", additional_info = "Objeto de misión\n[q2]Uso: Invoca un hipogrifo para que te lleve volando rápidamente desde Lunedane a Valdrakken.\n[q]\"Un silbato pequeño de bosquerruna que emite un trino agudo.\""}
MultiLanguageItemData['mx'][206354] = {name = "[q3]Vela maloliente", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Perfecto para esos días en los que no quieres que nadie te moleste.\""}
MultiLanguageItemData['mx'][206355] = {name = "[q3]Vela llena de tabaco", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Cuando el mensajero se retrasa, a veces es necesario encargarse personalmente de resolver las cosas.\""}
MultiLanguageItemData['mx'][206356] = {name = "[q3]Vela de amparo contra fantasmas", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Se supone que ahuyenta a los fantasmas, pero es evidente que eso es solo un cuento para niños.\""}
MultiLanguageItemData['mx'][206357] = {name = "[q3]Vela de Andorhal auténtica", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Una vela tan común que termina pareciendo sospechosa.\""}
MultiLanguageItemData['mx'][206358] = {name = "[q3]Vela importada", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"El detalle más llamativo de esta vela son las palabras que alguien logró grabar en la parte inferior: “Cruce de Corin”.\""}
