MultiLanguageItemData['mx'][206361] = {name = "[q2]Muñeca pisoteada", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Una nota arrugada que está guardada en uno de los bolsillos de la muñeca dice: “Para el mejor de mis mejores amigos, de Pamela”.\""}
