MultiLanguageItemData['mx'][206363] = {name = "[q2]El camino por delante", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Una hermosa pintura del camino que lleva a Cruce de Corin. En una de las esquinas, aparece la firma “Renfray” inscrita con esmero.\""}
