MultiLanguageItemData['mx'][206563] = {name = "[q4]Patrón antiguo: sudario de magia prohibida", additional_info = "[q2]Uso: Te enseña a fabricar un sudario de magia prohibida.\nRequiere Sastrería clásica (300)\n\n\n[q4]Sudario de magia prohibida\nCosmético\nSe liga al equiparlo\n{Cabeza} {Cosmético}\n[q2]Uso: Añade esta apariencia a tu colección de tropa.\nPrecio de venta:\nRequiere Chatarra asolada por la guerra (200), Esencia de no-muerto (100), Tela vil (50), Fragmento luminoso grande (60), Runa oscura (25), Tinte fantasmal (20)"}
MultiLanguageItemData['mx'][206564] = {name = "Disco titánico cronodesplazado", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\n[q]\"Un objeto que, obviamente, tiene origen titánico. A pesar de la saliva que gotea, parece que todavía funciona.\""}
MultiLanguageItemData['mx'][206565] = {name = "[q3]Grano apestado", additional_info = "Se liga al recogerlo\nJuguete\n[q2]Uso: Coloca un cajón de grano común durante 3 min. Nadie sospechará nada. (2 H Reutilización)\n[q]\"Una caja con matasellos de la Capilla de la Esperanza de la Luz. Afortunadamente, nunca llegó.\""}
MultiLanguageItemData['mx'][206566] = {name = "[q4]Riendas del pterrordáctilo escarlata", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar a un pterrordáctilo escarlata.\n[q2]Invoca y retira a tu pterrordáctilo escarlata.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Este pterrordáctilo estaba tan ansioso por alzar vuelo que su cuidador no pudo completar su entrenamiento.\"\nMisión:\nHora de volar"}
MultiLanguageItemData['mx'][206567] = {name = "[q4]Grifo de puerto", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar a un Grifo de puerto.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Este grifo era el más débil de su grupo. Cuando el resto inició su entrenamiento, él fue dejado de lado. Sin embargo, hoy está listo para probar su valor.\"\nMisión:\nHora de volar"}
