MultiLanguageItemData['mx'][208725] = {name = "[q4]Escamas del acaparador de plata", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Reúne las apariencias de las Escamas del acaparador de plata.\n[q]\"Forjada por un forjatiempo desconocido en una época desconocida.\""}
MultiLanguageItemData['mx'][208726] = {name = "[q4]Tesoro del acaparador de plata", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Reúne las apariencias del Tesoro del acaparador de plata.\n[q]\"Diseñadas por un antiguo herrero, los forjatiempos viajaron a su tiempo para crear estas armas como respuesta a una necesidad futura. Con el tiempo, se descubrirá cuál es esa necesidad.\""}
MultiLanguageItemData['mx'][208727] = {name = "[q4]Camuflaje del cazador zancacuernos", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Reúne las apariencias del Camuflaje del guerrero zancacuernos.\n[q]\"Mientras se preparan para una cacería de zancacuernos, los cazadores veteranos se ponen este atuendo ceremonial para inspirar a los cazadores novatos en su primera cacería.\""}
MultiLanguageItemData['mx'][208728] = {name = "[q4]Preferencia del cazador zancacuernos", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Reúne las apariencias de la Preferencia del guerrero zancacuernos.\n[q]\"Conocidos por su destreza y ferocidad, los zancacuernos son una presa excelente y proporcionan un material aún mejor para fabricar armas.\""}
MultiLanguageItemData['mx'][208729] = {name = "[q4]Inminencia del ejecutor de Krag'wa", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Reúne las apariencias de la Inminencia de ejecutor de Krag'wa.\n[q]\"Fabricada para los sumos sacerdotes de Krag'wa y los seguidores más fervientes de los loa.\""}
MultiLanguageItemData['mx'][208730] = {name = "[q4]Herramientas del ejecutor de Krag'wa", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Reúne las apariencias de las Herramientas de ejecutor de Krag'wa.\n[q]\"Los templos de Krag'wa estaban custodiados por leales zandalari que empuñaban armas diseñadas para honrar y proteger.\""}
