MultiLanguageItemData['mx'][208937] = {name = "Un diario embarrado", additional_info = "[q]\"Encontraste este diario en el césped, por lo que sus páginas están cubiertas de barro. Las últimas páginas contienen una pequeña visión de un alma herida.\"\n[q2]<Click derecho para leer>\nPrecio de venta:"}
