MultiLanguageItemData['mx'][208939] = {name = "[q4]Gorridar, hoja oscura de taladora", additional_info = "Cosmético\n[q7]Se liga a la tropa\n{Una mano} {Espada}\n{1 p. de daño} {Velocidad 2.60}\n(0.4 p. de daño por segundo)\nEste objeto no está disponible para la venta directa. Consulta tu registro de viajero para saber cómo obtener el alijo de armas cósmicas.\n[q]\"La malicia y el odio se fusionaron en un arma diseñada para arrasar con mundos enteros. Cuídate de cualquiera que envidie una espada semejante.\"\n[q2]Uso: Añade esta apariencia a tu colección de tropa.\nPrecio de venta:"}
MultiLanguageItemData['mx'][208940] = {name = "[q4]Cantovacío, báculo de presagista", additional_info = "Cosmético\n[q7]Se liga a la tropa\n{Dos manos} {Bastón}\n{1 - 2 p. de daño} {Velocidad 3.60}\n(0.4 p. de daño por segundo)\nEste objeto no está disponible para la venta directa. Consulta tu registro de viajero para saber cómo obtener el alijo de armas cósmicas.\n[q]\"Un regalo de Dimensius otorgado en el punto álgido del Imperio Negro. Sus susurros hechizantes atraen a quienes están tocados por la sombra.\"\n[q2]Uso: Añade esta apariencia a tu colección de tropa.\nPrecio de venta:"}
MultiLanguageItemData['mx'][208941] = {name = "[q4]M'thorus, daga del Gran Diseño", additional_info = "Cosmético\n[q7]Se liga a la tropa\n{Una mano} {Daga}\n{1 p. de daño} {Velocidad 1.80}\n(0.6 p. de daño por segundo)\nEste objeto no está disponible para la venta directa. Consulta tu registro de viajero para saber cómo obtener el alijo de armas cósmicas.\n[q]\"Los sombras no pueden propagarse. Hay que derrotar el desorden dondequiera que se arraigue. Los verdaderos hijos de los titanes responderán al llamado de sus creadores.\"\n[q2]Uso: Añade esta apariencia a tu colección de tropa.\nPrecio de venta:"}
MultiLanguageItemData['mx'][208942] = {name = "Informe número tres de conservacionista", additional_info = "Los Secretos de Azeroth\nSe liga al recogerlo\n[q]\"Una nota que describe un artefacto de orbe que necesitan los conservacionistas.\"\n[q2]<Click derecho para leer>"}
MultiLanguageItemData['mx'][208943] = {name = "[q4]Arsenal: Alijo de armas cósmicas", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Reúne las apariencias contenidas en el Alijo de armas cósmicas.\n[q]\"Armamentos forjados a partir del material primigenio del cosmos. Hasta hoy es un misterio quién recopiló esta colección y para qué. Quien los empuñe llamará la atención de los que desean semejante poder.\""}
MultiLanguageItemData['mx'][208944] = {name = "Orbe de Rathmus", additional_info = "Los Secretos de Azeroth\nSe liga al recogerlo\nEste objeto inicia una misión\n[q]\"Símbolos titánicos embellecen las bandas metálicas que rodean al orbe brillante.\""}
MultiLanguageItemData['mx'][208945] = {name = "[q7]Cajón paracausal", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Abre para obtener 500 copos paracausales.\n[q]\"Lamentablemente, por el bien de la línea temporal, se recomienda abrir esto antes de enviarlo.\""}
MultiLanguageItemData['mx'][208946] = {name = "Runa ardiente", additional_info = "Objeto de misión\n[q]\"Un grabado misterioso que emana un calor molesto.\""}
MultiLanguageItemData['mx'][208947] = {name = "Regadera encantada", additional_info = "Objeto de misión\nÚnico\n[q2]Uso: Rocía agua sobre arbustos encantados, lo que les da la energía para que se entreguen a Magnolia Robles.\n[q]\"Más poderosa que una regadera normal.\""}
