MultiLanguageItemData['mx'][208950] = {name = "Fibra esmeralda", additional_info = "Objeto de misión\n[q]\"Una fibra compacta que posee una resistencia extraordinaria a la tensión.\""}
MultiLanguageItemData['mx'][208951] = {name = "[q7]Cúmulo paracausal", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Muele para obtener 1000 copos paracausales.\n[q]\"Una formación de cristales que surge justo antes de la colisión de dos portales del tiempo, hecha con arenas del tiempo comprimidas.\""}
