MultiLanguageItemData['mx'][209996] = {name = "Runa de lazorraíz", additional_info = "Se liga al recogerlo\n[q2]Uso: Te infliges Succión de lazorraíz al unirte a cualquier criatura rara del Sueño esmeralda.\n\n Derrotar a criaturas raras mientras Succión de lazorraíz está activa otorga lazorraíz firme. (5 Seg Reutilización)\n[q]\"Runa de Lydiara para succionar rollo vinculante tenso de las criaturas poderosas del Sueño Esmeralda.\""}
MultiLanguageItemData['mx'][209997] = {name = "[q3]Conocimiento destilado de los portales del tiempo", additional_info = "[q7]Se liga a la tropa\nÚnico (5)\n[q2]Uso: Aumenta un 5% la experiencia obtenida por matar monstruos y completar misiones.\n\n Completar calabozos de cronoviaje aumenta el efecto y extiende la duración.\n\n Cuando llega a 4 aplicaciones, se transforma en Maestría de los portales del tiempo , lo que aumenta el efecto a un 30%."}
MultiLanguageItemData['mx'][209998] = {name = "[q4]Runa de vinculación de Lydiara.", additional_info = "Se liga al recogerlo\n[q]\"Se fabrica junto con Lydiara Susurraplumas.\""}
MultiLanguageItemData['mx'][209999] = {name = "Runa de vinculación lóbrega de Lydiara", additional_info = "Se liga al recogerlo\n[q2]Uso: Te vinculas con Nudorraíz, Igira o Volcoross y quedas en estado de Vinculasombras.\n\n Mientras estás en ese estado, te ves afectado por Llama de las sombras rugiente, que te ralentiza entre un 0 y un 50% según tu distancia al objetivo, y tiene la probabilidad de obstaculizar tu movilidad cada 5 s. (5 Seg Reutilización)\n[q]\"Una runa de vinculación lóbrega lista para la armonización con Fyr'alath.\""}
MultiLanguageItemData['mx'][210001] = {name = "[q4]Prototipo de vitela de orden", additional_info = "Se liga al recogerlo\n[q]\"Un prototipo de vitela fabricado por Shalasar a partir de motas de ceniza radiante.\""}
MultiLanguageItemData['mx'][210002] = {name = "Vara de radiestesia cinérea", additional_info = "Objeto de misión\n[q2]Uso: Extrae motas radiantes de ceniza de armas o armaduras de calidad poderosa (ÉPICA). El objeto elegido será DESTRUIDO y no se podrá recuperar. (5 Min Reutilización)\n[q]\"Una vara de radiestesia que otorga al usuario la habilidad de desencantar piezas poderosas de equipo para buscar motas radiantes de ceniza.\""}
MultiLanguageItemData['mx'][210003] = {name = "[q4]Vitela sapiencial de Shalasar", additional_info = "Se liga al recogerlo\n[q]\"Se fabrica junto con Shalasar Destellocaso.\""}
MultiLanguageItemData['mx'][210005] = {name = "[q3]10.2 Monster - Weapon - Staff - 10.1.5 Weapon Staff - Staff_2H_Druid_C_02_Color1", additional_info = "Se liga al equiparlo\n{Dos manos} {Bastón}\n{7 - 10 p. de daño} {Velocidad 3.60}\n(2.4 p. de daño por segundo)\n+28 intelecto\n+9 aguante\n[q2]Aumenta tu índice de golpe crítico + 8 p.\n[q2]Aumenta tu índice de celeridad + 5 p.\nPrecio de venta:"}
MultiLanguageItemData['mx'][210008] = {name = "[q4]Runa humeante de vinculación", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"¡Purga con fuego los obstáculos que encuentres en tu camino!\"\nPromoción:\nCataclysm Classic"}
MultiLanguageItemData['mx'][210009] = {name = "[q4]Prototipo de empuñadura de frondasueño", additional_info = "Se liga al recogerlo\n[q]\"Un prototipo de runa fabricada por Erden a partir de frondasueño ensombrecida.\""}
MultiLanguageItemData['mx'][210010] = {name = "Notas de Erden sobre esporas simbióticas", additional_info = "Se liga al recogerlo\n[q2]Uso: Comparte las notas de Erden con un peletero aliado y enséñale temporalmente a fabricar la empuñadura de frondasueño de Erden. El peletero debe pertenecer al mismo grupo. (30 Min Reutilización)\n[q]\"Notas que detallan todo lo necesario para fabricar una empuñadura de brilloesporas simbióticas experimental. Escritas por el maestro peletero Erden.\""}
MultiLanguageItemData['mx'][210011] = {name = "Notas de Shalasar sobre magia sapiencial", additional_info = "Se liga al recogerlo\n[q2]Uso: Comparte las notas de Shalasar con un encantador aliado y enséñale temporalmente a fabricar la vitela sapiencial de Shalasar. El encantador debe pertenecer al mismo grupo. (30 Min Reutilización)\n[q]\"Notas que detallan todo lo necesario para fabricar una vitela sapiencial experimental. Escritas por la maestra encantadora Shalasar Destellocaso.\""}
MultiLanguageItemData['mx'][210012] = {name = "Empuñadura de brilloesporas simbióticas de Erden", additional_info = "Se liga al recogerlo\n[q2]Uso: Intentas vincular la Empuñadura de brilloesporas simbióticas a Fyr'alath, lo que te inflige entre un 10% y un 25% de tu salud máxima como daño de pirosombra por segundo cada 10 s. (30 Seg Reutilización)\n[q]\"Una empuñadura de brilloesporas sin probar.\""}
MultiLanguageItemData['mx'][210014] = {name = "[q3]Semillas atemporales misteriosas", additional_info = "Objeto de misión\nÚnico (20)\n[q2]Uso: Siembra una semilla del tamaño adecuado en una parcela cercana de tierra de semilla onírica.\n[q]\"Semillas oníricas que esperan que las despierten.\""}
MultiLanguageItemData['mx'][210016] = {name = "Sudario de soñobúho", additional_info = "Objeto de misión\nÚnico\n[q2]Uso: Entras en sigilo. Si entras en combate o lanzas una habilidad, se interrumpirá el efecto. Los enemigos te detectarán si estás demasiado cerca de ellos. (8 Seg Reutilización)\n[q]\"Invoca a soñobúho Bodwin para que te dé un aura de sigilo temporal.\""}
