MultiLanguageItemData['mx'][210057] = {name = "[q4]Riendas del Sableonírico del florecimiento matutino", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiere reconocimiento 18 con los Celadores Oníricos.\nRequiere nivel 18 de reconocimiento con los Celadores Oníricos.\nPrecio de venta:\n[q]\"Conocidos por tener una energía exuberante, estos sableoníricos también tienen fama de ser bromistas. Con su rugido, espantan a las aves que los despiertan a la mañana.\"\nVendedora:\nTalisa Florsusurrante\nZona:\nSueño Esmeralda\nCosto:\n1"}
MultiLanguageItemData['mx'][210058] = {name = "[q4]Riendas del Sableonírico soleado diurno", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiere reconocimiento 18 con los Celadores Oníricos.\nRequiere nivel 18 de reconocimiento con los Celadores Oníricos.\nPrecio de venta:\n[q]\"Estos sableoníricos son feroces en una batalla, pero suelen estar estirados sobre el suelo, en un estado de letargo. Después de echarse bajo el sol, sus llamas brillan con mucha más intensidad.\"\nVendedora:\nTalisa Florsusurrante\nZona:\nSueño Esmeralda\nCosto:\n1"}
MultiLanguageItemData['mx'][210059] = {name = "[q4]Riendas del Sableonírico nocturno invernal", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Estos sableoníricos nocturnos llevan el frío del invierno en su interior y son capaces de hibernar durante varios días seguidos si nadie interrumpe su sueño.\"\nBotín:\nAlijo de semilla onírica\nZona:\nSueño Esmeralda"}
MultiLanguageItemData['mx'][210060] = {name = "[q4]Riendas del Sableonírico del anochecer sombrío", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Los sableoníricos atacan rápidamente desde las sombras para capturar animales pequeños, y luego vuelven a la oscuridad sin producir un solo ruido. Los pocos afortunados que han visto a un sableonírico a punto de comer cuentan que la criatura se regocija jugando con su presa antes de devorarla.\"\nLogro:\nGloria del Asaltante del Sueño\nCategoría:\nCalabozos y bandas"}
MultiLanguageItemData['mx'][210061] = {name = "[q4]Riendas de Anu'relos, Guía de la Llama", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a Anu'relos, Guía de la Llama.\n\n Esta montura puede usar Montar en compañía.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Aunque en sus plumas se entrevé el potencial destructivo de la llama, en realidad no calcinan, solo irradian un calor agradable.\"\nBotín:\nFyrakk\nZona:\nAmirdrassil, la Esperanza del Sueño (Mítico)"}
