MultiLanguageItemData['mx'][210185] = {name = "[q4]Poción salpicante de narcolepsia", additional_info = "Se liga al recogerlo\n[q2]Uso: Estudia para aumentar 3 p. tu conocimiento de alquimia de las Islas Dragón.\nRequiere Alquimia de las Islas Dragón (25)\n[q]\"Su meta aparente es poner a dormir a un objetivo, así que parece un poco contraintuitivo tener que salpicarlos en el proceso.\""}
MultiLanguageItemData['mx'][210189] = {name = "Lente de artificio del exarca Hataaru", additional_info = "Objeto de misión\n[q]\"Un lente dorado pequeño, desgastado por el tiempo y el uso. Las facetas talladas con precisión ayudan a que los artificieros vean las vías energéticas que recorren los cristales que usan en su trabajo.\""}
MultiLanguageItemData['mx'][210190] = {name = "[q4]Lumbrerraíz", additional_info = "Se liga al recogerlo\n[q2]Uso: Estudia para aumentar 3 p. tu conocimiento de alquimia de las Islas Dragón.\nRequiere Alquimia de las Islas Dragón (25)\n[q]\"Quema al tacto. Sería un catalizador excelente para tus pociones, pero buena suerte para convencer a un herborista de que juegue con fuego.\""}
MultiLanguageItemData['mx'][210193] = {name = "[q4]Atrapasueños experimental", additional_info = "Se liga al recogerlo\n[q2]Uso: Estudia para aumentar 3 p. tu conocimiento de ingeniería de las Islas Dragón.\nRequiere Ingeniería de las Islas Dragón (25)\n[q]\"Llevar un imán al Sueño Esmeralda no lo convierte automáticamente en un atrapasueños, pero alguien tenía que intentarlo.\""}
MultiLanguageItemData['mx'][210194] = {name = "[q4]Insomniotrón", additional_info = "Se liga al recogerlo\n[q2]Uso: Estudia para aumentar 3 p. tu conocimiento de ingeniería de las Islas Dragón.\nRequiere Ingeniería de las Islas Dragón (25)\n[q]\"Un dispositivo calibrado cuidadosamente que emite un sonido agudo que solo pueden oír los druidas durmientes.\""}
