MultiLanguageItemData['mx'][210454] = {name = "Hologema sobrante", additional_info = "Objeto de misión\n[q2]Uso: Te teletransporta a las coordenadas almacenadas en el recuerdo de la hologema. (30 Seg Reutilización)\n1 carga\n[q]\"Una multiherramienta draénica común que suele usarse para guardar hechizos de teletransportación y comunicarse a larga distancia.\""}
