MultiLanguageItemData['mx'][210826] = {name = "[q2]Kit de reparación de cosechabot", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Aprende los fundamentos básicos que te permiten utilizar remanentes radiantes para reparar cosechabots desactivados.\n\n Cuando estén reparados, te ayudarán a luchar contra los enemigos que estén cerca de ellos.\n[q]\"Instrucciones y herramientas de Ezgi para reparar cosechabots.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][210827] = {name = "[q4]Artilugio de Ezgi", additional_info = "Se liga al recogerlo\nÚnico (10)\n[q2]Uso: Una señal de emergencia que activa a los cosechabots disponibles para que ayuden a eliminar cualquier amenaza del Estanque Petrocalmo y la Mina Luz de Antorcha.\nRequiere reconocimiento 12 con los Arathi de Cristalia.\n[q]\"¡Una vez que aprendes a reparar uno, el resto es fácil!\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][210828] = {name = "Solución diluyente", additional_info = "Se liga al recogerlo\nMaterial de profesión\n[q]\"Un reactivo alquímico utilizado para neutralizar los efectos de pociones y frascos. Se puede adquirir de cualquier proveedor de alquimia de Khaz Algar.\"\nPrecio de venta:"}
