MultiLanguageItemData['mx'][212289] = {name = "Frasco sañoso de licores clásicos", additional_info = "[q2]Uso: Bebe para aumentar tu regeneración de maná un 8% si no has lanzado ningún hechizo beneficioso que cueste maná durante 5 s.\n\n El honor obtenido aumenta un 15%.\n\nDura 1 h y persiste después de la muerte. Consumir un frasco idéntico añade 1 h más.\nPrecio de venta:"}
