MultiLanguageItemData['mx'][213020] = {name = "[q2]Pala dracónida antigua", additional_info = "Se liga al recogerlo\n[q2]Uso: Destroza esta reliquia en pocos fragmentos misteriosos.\n[q]\"A través de un análisis exhaustivo, es posible determinar la fecha de creación de esta pala, pero lo más importante es que ese proceso revelará la época en que surgió la agricultura.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213021] = {name = "[q2]Vial dracónido con corcho", additional_info = "Se liga al recogerlo\n[q2]Uso: Destroza esta reliquia en pocos fragmentos misteriosos.\n[q]\"El corcho parece haberse fusionado con la botella después de descomponerse durante una eternidad. Se podría aprender mucho si se abre este objeto, pero también si se mantiene como está.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213022] = {name = "[q2]Martillo de herrero dracónido", additional_info = "Se liga al recogerlo\n[q2]Uso: Destroza esta reliquia en pocos fragmentos misteriosos.\n[q]\"Aunque es casi imposible determinar la antigüedad de este martillo, los materiales que se usaron para forjarlo revelan mucho acerca de la tecnología de esa civilización.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213023] = {name = "[q2]Antorcha djaradin empapada de aceite", additional_info = "Se liga al recogerlo\n[q2]Uso: Destroza esta reliquia en pocos fragmentos misteriosos.\n[q]\"Cuando los djaradin descubrieron el aceite, no tuvieron reservas al momento de usarlo. Las fogatas, las armas y hasta el entretenimiento recibieron el impacto de este nuevo descubrimiento.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213024] = {name = "[q2]Jarra djaradin sangrienta", additional_info = "Se liga al recogerlo\n[q2]Uso: Destroza esta reliquia en pocos fragmentos misteriosos.\n[q]\"Poco se sabe acerca de los detalles de la cultura de los djaradin, pero se puede llegar a ciertas conclusiones cuando se descubre una jarra manchada con sangre.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213025] = {name = "[q2]Saeta djaradin antigua", additional_info = "Se liga al recogerlo\n[q2]Uso: Destroza esta reliquia en pocos fragmentos misteriosos.\n[q]\"Las armas de los djaradin han evolucionado poco desde que este pueblo al poder, y son tan crueles ahora como hace un siglo.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213026] = {name = "[q0]Pincel dracónido enorme", additional_info = "[q]\"Los dragonantes más grandes usaban estos pinceles con una habilidad asombrosa, y pintaban desde hogares hasta murales intrincados.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213027] = {name = "[q0]Taza dracónido partida", additional_info = "[q]\"Este cáliz estropeado valía una fortuna en su época de auge. Sin embargo, ahora solo se podrían conseguir unas pocas monedas en el mercado local.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213028] = {name = "[q0]Compás roto", additional_info = "[q]\"Antes se empleaba para crear archivos enteros de mapas y cartas náuticas. Encontrar un compás es solo el primer paso para descubrir la capacidad tecnológica de una civilización antigua.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213029] = {name = "[q0]Tenedor dracónido doblado", additional_info = "[q]\"Un tenedor dracónido podría parecer mundano para los ojos más inexpertos, pero esta herramienta oculta la sofisticación de su creador.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213030] = {name = "[q0]Tijeras de jardín oxidadas", additional_info = "[q]\"La mancha diminuta de sangre que adorna la punta de las tijeras podría explicar por qué un jardinero frustrado las descartó hace mucho tiempo.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213031] = {name = "[q0]Cáliz dracónido deformado", additional_info = "[q]\"Los años han hecho estragos en este cáliz, pero un buen ojo puede aprender mucho a partir de sus restos.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213032] = {name = "[q0]Vasija dracónida deformada", additional_info = "[q]\"La tapa ya no encaja en esta vasija, pero ahora se puede usar como un plato pequeño.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213033] = {name = "[q0]Tenazas de herrería frágiles", additional_info = "[q]\"Estas tenazas han visto muchas batallas y han avivado varias llamas durante siglos. Unas pequeñas imperfecciones y grietas en el metal revelan mucho sobre su uso.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213034] = {name = "[q0]Cuenco dracónido partido", additional_info = "[q]\"Este hermoso cuenco ya no tiene ningún uso práctico, pero sería una excelente pieza central en la galería de cualquier arqueólogo.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213035] = {name = "[q0]Pincel dracthyr endurecido", additional_info = "[q]\"Este pincel cubierto de una variedad de pinturas secas está repleto de muestras de especímenes de varios pigmentos y soluciones.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213037] = {name = "[q0]Pala de jardinería dentada", additional_info = "[q]\"Los años de uso han hecho que esta pala quede completamente inutilizable. Ah, las historias que podría contar.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213038] = {name = "[q0]Lupa rota", additional_info = "[q]\"Este objeto podría haber sido útil para leer la letra chica de los planes que Neltharion ideó para los dracthyr.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213039] = {name = "[q0]Cuchara dracónida delgada", additional_info = "[q]\"Desde los utensilios hasta los cubiertos sirven para contar historias acerca de la vida cotidiana del pueblo local.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213040] = {name = "[q0]Amuleto djaradin deslustrado", additional_info = "[q]\"Los elementos hicieron que las inscripciones de este amuleto sean indescifrables, pero la forma que conserva podría ayudar a entender las costumbres de los djaradin.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213041] = {name = "[q0]Pergamino djaradin desecado", additional_info = "[q]\"Después de recolectar rigurosamente los trozos necesarios para recomponer este descubrimiento, resulta que este pergamino está repleto de garabatos sin sentido.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213042] = {name = "[q0]Estandarte djaradin deteriorado", additional_info = "[q]\"Un estandarte djaradin que ondeó durante tiempos de guerra y de paz. Las grietas y desgarros que sufrió a lo largo del tiempo dejan en evidencia su antigüedad.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213043] = {name = "[q0]Cuero djaradin quebradizo", additional_info = "[q]\"Este cuero, que difícilmente podría utilizarse como componente de fabricación, tiene un origen desconocido que es mejor dejar a la imaginación.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213044] = {name = "[q0]Amuleto de colmillos raído", additional_info = "[q]\"Al observarlo de cerca, el colmillo de este amuleto parece haber sido de un djaradin. ¿Tal vez sea un trofeo de batalla?\"\nPrecio de venta:"}
