MultiLanguageItemData['mx'][213192] = {name = "[q2]Lista de nombres tachados", additional_info = "Se liga al recogerlo\n[q2]Uso: Destroza esta reliquia en pocos fragmentos misteriosos.\n[q]\"Alguien se aseguró de que cada nombre fuera ilegible antes de descartar la lista.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213193] = {name = "Medallón del ejército arathi", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\n[q]\"La superficie pulida está mugrienta.\""}
MultiLanguageItemData['mx'][213194] = {name = "[q0]Raciones petrificadas", additional_info = "[q]\"Este cúmulo de alimento endurecido ofrece un vistazo de lo que se comía en esta isla.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213195] = {name = "[q0]Garabato calcinado", additional_info = "[q]\"La mayor parte del papel se ha destruido, pero en las partes que se logran distinguir ves cuernos y cejas que muestran enojo.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213196] = {name = "[q0]Flor prensada", additional_info = "[q]\"Esta flor se secó y se prensó, preservada entre las páginas de un libro perdido en el tiempo.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213197] = {name = "[q3]Loto nulo", additional_info = "Material de profesión\n[q]\"Una hierba extraña que transmite una sensación de vacío. A veces, la recolectan jugadores con habilidad en herboristería. Se puede comprar y vender en la casa de subastas.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213200] = {name = "[q2]Libro de horóscopos", additional_info = "Se liga al recogerlo\n[q2]Uso: Destroza esta reliquia en pocos fragmentos misteriosos.\n[q]\"Es una maravilla que un libro así de frágil haya sobrevivido. Los garabatos en su interior sugieren que alguien se tomó muy en serio todas estas tonterías.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213201] = {name = "[q0]Huesos de ave acuática desechados", additional_info = "[q]\"Los dragonantes de este lugar eran fanáticos de los patos, pero estos huesos sugieren que, de vez en cuando, también se los comían.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213202] = {name = "[q2]Sombrero de expedicionario diminuto", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Cuando lo invocas, Pepe aparecerá algunas veces disfrazado de expedicionario."}
MultiLanguageItemData['mx'][213203] = {name = "[q0]Gorro para dormir de terciopelo", additional_info = "[q]\"Esta capucha magnífica debe haber pertenecido a alguien importante. Tiene dos agujeros para cuernos.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213204] = {name = "[q2]Guardapelo adornado con rubíes", additional_info = "Se liga al recogerlo\n[q2]Uso: Destroza esta reliquia en pocos fragmentos misteriosos.\n[q]\"Contiene un boceto de un dracónido rojo con una sonrisa espléndida.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213205] = {name = "[q0]Garabatos dementes", additional_info = "[q]\"Estos mapas celestas se extienden mucho más allá de la realidad. Estudiar las estrellas no es para los débiles.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213206] = {name = "[q0]Carta calcinada", additional_info = "[q]\"Lo poco que se puede leer indica que esto era una refutación enojada de un compañero erudito.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213207] = {name = "[q2]Unas orejeras diminutas", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Cuando lo invocas, Pepe aparecerá algunas veces disfrazado de colmillarr."}
MultiLanguageItemData['mx'][213208] = {name = "[q2]Anchovas en conserva", additional_info = "Se liga al recogerlo\n[q2]Uso: Destroza esta reliquia en pocos fragmentos misteriosos.\n[q]\"Alguien debía estar guardándolas para una ocasión especial que nunca se dio.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213209] = {name = "Huevo de larva", additional_info = "Objeto de misión\nÚnico (20)\n[q]\"Tibio y palpitante. Seguramente es un manjar kóbold.\""}
MultiLanguageItemData['mx'][213210] = {name = "[q0]Retazo de estandarte ensangrentado", additional_info = "[q]\"Este trozo de tela arrancado se usó como venda en algún momento.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213211] = {name = "[q0]Pétalos de flor petrificados", additional_info = "[q]\"Estos pétalos se arrancaron uno a uno y se tiraron sobre magma que se estaba enfriando.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213212] = {name = "[q0]Cuchillo de huesos de ballena", additional_info = "[q]\"Los pescadores colmillarr siempre llevaban uno. Son útiles para cortar cuerdas.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213213] = {name = "[q0]Hongos de cueva secos", additional_info = "[q]\"Aun disecados, se parecen a los hongos que se cultivan hoy en día en Caverna Zaralek.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213214] = {name = "[q0]Cesta de lavajuncos tejida", additional_info = "[q]\"Hecha de hierbas resistentes al calor. Su diseño recuerda al de una trampa para cangrejos tejida colmillarr.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213215] = {name = "[q2]Piedra votiva tallada", additional_info = "Se liga al recogerlo\n[q2]Uso: Destroza esta reliquia en pocos fragmentos misteriosos.\n[q]\"Se ha tallado un rostro en la piedra, para ofrecer a alguna deidad djaradin desconocida.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213216] = {name = "[q0]Tira de cuero dentado", additional_info = "[q]\"Este pedazo de cuero se ha marcado decenas de veces, aunque nadie sabe qué conmemora.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213217] = {name = "Meca-jarly", additional_info = "Consumible\n[q2]Uso: Invoca a una meca-jarly con lugar para dos pasajeros. ¡Saquea a lo grande!\n\n Viene equipada con un acelerón de velocidad. Ten cuidado con el botón de autodestrucción.\nPrecio de venta:"}
MultiLanguageItemData['mx'][213218] = {name = "Veneno de la reina Rickiticka", additional_info = "Objeto de misión\nÚnico\n[q]\"Un antídoto poderoso. Al menos, en dosis adecuadas.\""}
MultiLanguageItemData['mx'][213224] = {name = "Carta de Hearthstone: Mano de protección", additional_info = "Se liga al recogerlo\n[q2]Uso: Agrega esta carta a tu colección."}
MultiLanguageItemData['mx'][213232] = {name = "Tiempo embotellado", additional_info = "Consumible\n[q2]Uso: Destroza la botella en el piso y crea una zona que acelera el tiempo de reutilización de TODOS los piratas durante un periodo corto.\n\n No te preocupes por la botella, no era importante.\nPrecio de venta:"}
