MultiLanguageItemData['mx'][213357] = {name = "[q2]Cuenco de visión de cristal", additional_info = "Se liga al recogerlo\n[q2]Uso: Destroza esta reliquia en pocos fragmentos misteriosos.\n[q]\"Al contemplar el cuenco, sientes que casi puedes dilucidar una imagen. O quizás sea tu reflejo.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213358] = {name = "[q0]Calavera excavada inadecuadamente", additional_info = "[q]\"Quizás este hallazgo poco común podría habernos iluminado con una gran sabiduría, ¡pero quien sea que lo descubrió lo atravesó con una piqueta!\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213359] = {name = "[q2]Bastón dracónido partido", additional_info = "Se liga al recogerlo\n[q2]Uso: Destroza esta reliquia en pocos fragmentos misteriosos.\n[q]\"El tiempo ha dejado inutilizable al foco mágico, pero los grabados de la vara cuentan otra historia más profunda.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213360] = {name = "[q0]Amuleto dracónido descartado", additional_info = "[q]\"Después de que se arrancara la gema de este amuleto, su valor se redujo a prácticamente nada.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213361] = {name = "[q0]Juguete para niños desconcertante", additional_info = "[q]\"Los niños han desarrollado una fascinación preocupante por estos muñecos perturbadores. Quizás sea mejor no investigar mucho.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213362] = {name = "[q0]Antiguo dulce dracónido", additional_info = "[q2]Uso: Cómeme.\n[q]\"Puede que haya conservado su forma, pero es innegable que este caramelo dracónido duro como piedra ya ha superado su fecha de caducidad.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213363] = {name = "[q0]Piel del ojo fundida", additional_info = "[q]\"Cuando los reptiles mudan las escamas, muchas especies también mudan la piel de los ojos. Durante este tiempo, estas criaturas suelen quedar ciegas e indefensas.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213364] = {name = "[q0]Vial de perfume vacío", additional_info = "[q]\"El borde aún conserva un aroma encantador.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213365] = {name = "[q2]Cristal de cueva grabado", additional_info = "Se liga al recogerlo\n[q2]Uso: Destroza esta reliquia en pocos fragmentos misteriosos.\n[q]\"Se han grabado formas intrincadas en este cristal, por lo que la luz que desprende forma patrones únicos.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213366] = {name = "[q0]Trozo de cubrecabezas olfatopo", additional_info = "[q]\"Si se compara el material y el diseño de este gorro olfatopo con el de los más comunes de hoy en día, se puede extrapolar la evolución de la moda olfatopo.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213367] = {name = "[q0]Prototipo de garra descartado", additional_info = "[q]\"Podría decirse que es un intento rudimentario de mejorar las capacidades de excavación de los olfatopos. Al parecer, el proyecto se abandonó porque fue considerado innecesario.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213368] = {name = "[q0]Piedra para hurgar y olfatear", additional_info = "[q]\"Rayar esta piedra va en contra de todos los principios arqueológicos. Pero ganas no faltan.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213374] = {name = "[q0]Tapón para nariz olfatopo", additional_info = "[q]\"El olfato de los olfatopos es tan sensible que a veces necesitan algo para parar de sentir olores y dormir un poco.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213375] = {name = "[q2]Cartera de objetos valiosos enterrados", additional_info = "Se liga al recogerlo\n[q2]Uso: Destroza esta reliquia en pocos fragmentos misteriosos.\n[q]\"En el raro caso en donde un olfatopo se olvida de dónde enterró sus pequeños tesoros, estas carteras perdidas sirven como cápsulas del tiempo.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213377] = {name = "[q0]Libro de cuentos mutilado", additional_info = "[q]\"Las enormes garras de los olfatopos no se llevan bien con los libros delicados. Al menos lo intentaron.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213380] = {name = "[q0]Fósil equino imposible de identificar", additional_info = "[q]\"¿Este va con los huesos de centauros o de caballos?\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213382] = {name = "[q2]Fragmento de mapa centauro de caza", additional_info = "Se liga al recogerlo\n[q2]Uso: Destroza esta reliquia en pocos fragmentos misteriosos.\n[q]\"Se puede aprender mucho sobre los centauros lugareños a partir de la forma en la que cazan. Este fragmento de mapa muestra la sorprendente coordinación de los antiguos grupos de caza.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213384] = {name = "[q0]Muñeca con pelo de caballo", additional_info = "[q]\"Se ha pasado de generación en generación, y cada padre le agregó algo en su confección.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213385] = {name = "[q0]Cepillo duro", additional_info = "[q]\"No hay mayor señal de intimidad y confianza entre los centauros que cepillarse entre sí.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213386] = {name = "[q0]Punta de flecha de piedra desenterrada", additional_info = "[q]\"La forma y el tamaño de la punta de flecha revelan mucho sobre cómo se fue adaptando la cacería centaura a lo largo de los años.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213387] = {name = "[q0]Tallado centauro primitivo", additional_info = "[q]\"Muchos centauros de todas las llanuras comparten una pasión por el tallado, una tradición que data desde el inicio de los registros.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213388] = {name = "[q0]Pintura centaura descolorida", additional_info = "[q]\"Ser nómade implica que no puedas llevar tus pinturas rupestres contigo. Los ingeniosos centauros del pasado resolvieron este problema con sus propias pieles para pintar.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213389] = {name = "[q2]Diario antiguo de centauro", additional_info = "Se liga al recogerlo\n[q2]Uso: Destroza esta reliquia en pocos fragmentos misteriosos.\n[q]\"Parece estar escrito desde la perspectiva de un niño y retrata bastante cómo era la vida de los primeros centauros.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213392] = {name = "Granada de esencia", additional_info = "Objeto de misión\n[q2]Uso: Arroja una granada con un olor fuerte para aturdir a un caparazón bélico feral y alertar a los olfatopos rak-ush de su ubicación.\n[q]\"Una granada de producción nerubiana, llena con un agradable humo relajante. Si eres un alfazaque, claro.\""}
MultiLanguageItemData['mx'][213393] = {name = "[q3]Aspecto de mascarada dorada", additional_info = "Cosmético\n[q7]Se liga a la tropa\n{Cabeza} {Cosmético}\n[q]\"El brillo reluciente del oro oculta la identidad de quien lo use y cautiva la mirada de los demás.\"\n[q2]Uso: Añade esta apariencia a tu colección de tropa.\nPrecio de venta:"}
MultiLanguageItemData['mx'][213394] = {name = "[q3]Corona de ébano de la rosa roja", additional_info = "Cosmético\n[q7]Se liga a la tropa\n{Cabeza} {Cosmético}\n[q]\"Toda noche tiene su amanecer.\"\n[q2]Uso: Añade esta apariencia a tu colección de tropa.\nPrecio de venta:"}
MultiLanguageItemData['mx'][213395] = {name = "[q2]Guantes de velada de medianoche", additional_info = "Cosmético\n[q7]Se liga a la tropa\n{Manos} {Cosmético}\n[q]\"El atuendo ideal para un encuentro nocturno.\"\n[q2]Uso: Añade esta apariencia a tu colección de tropa.\nPrecio de venta:"}
MultiLanguageItemData['mx'][213396] = {name = "[q2]Tabardo clásico de medianoche", additional_info = "Cosmético\n[q7]Se liga a la tropa\nTabardo\n[q]\"Un tabardo sencillo para todo tipo de ocasión.\"\n[q2]Uso: Añade esta apariencia a tu colección de tropa."}
MultiLanguageItemData['mx'][213397] = {name = "Bocadillos para loro", additional_info = "Consumible\n[q2]Uso: ¡Invoca a un loro aliado y leal para que te “asista” en el combate!\n\n El loro intenta ralentizar a los enemigos cercanos con descargas de guano. El daño es mayoritariamente espiritual.\nPrecio de venta:"}
MultiLanguageItemData['mx'][213398] = {name = "Puñado de piedritas", additional_info = "Material de profesión\n[q]\"Lo obtienen los joyeros cuando prospectan menas algari. Se puede comprar y vender en la casa de subastas.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213399] = {name = "Vidrio relumbrante", additional_info = "Material de profesión\n[q]\"Lo obtienen los joyeros cuando prospectan menas algari. Se puede comprar y vender en la casa de subastas.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213400] = {name = "Muñeco de nieve extraño", additional_info = "Consumible\n[q2]Uso: Invoca a un muñeco de nieve extraño que crea una amplia zona helada. Los piratas enemigos se resbalan cuando atraviesan el área.\n\n El taumaturgo y sus aliados no se ven afectados.\nPrecio de venta:"}
MultiLanguageItemData['mx'][213402] = {name = "Cristal incriminante", additional_info = "Objeto de misión\n[q]\"Una piedra resplandeciente que encaja en un emanasombras nerubiano.\""}
