MultiLanguageItemData['mx'][213595] = {name = "[q4]Cuerda de surfeaviento emplumado", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. La montura cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Revise la velocidad del viento y la elevación actuales antes de montar. Evite árboles y objetos altos. No se realizarán devoluciones o reembolsos por cometas dañadas”. - Manual de instrucciones para surfeavientos\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][213596] = {name = "[q4]Riendas de corcel del viento de tormenta matutina", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. La montura cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Se dice que cuando un relámpago cae sobre el sol, una brillante bestia con roja armadura baja de los cielos. El corcel del viento de tormenta matutina nunca ha escuchado estas leyendas y ha estado siempre aquí.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][213597] = {name = "[q4]Riendas de corcel del viento del bosque", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. La montura cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"El pelaje de este corcel del viento no solo tiene el color de su hogar forestal, también suele tener pedazos de corteza y hojas.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][213598] = {name = "[q4]Riendas de corcel del viento elegante", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. La montura cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Los corceles del viento son extremadamente gentiles y fáciles de entrenar... si logras atraparlos.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][213600] = {name = "[q4]Riendas del quilen de mármol", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. La montura cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Creada por un hechicero mogu que le dio vida a su roca mascota favorita.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][213601] = {name = "[q4]Riendas de quilen guardián", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. La montura cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Cuando Quan el Implacable cayó en batalla, sus leales sabuesos esperaron su regreso. Han pasado miles de años, y aún esperan con paciencia.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][213602] = {name = "[q4]Riendas de la grulla de montar dorada", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Se dice que, una vez, un emperador pagó una gran suma por una grulla de oro. Cuando descubrió que la grulla tan solo estaba pintada para parecerse al precioso metal, se escondió en su recámara durante una semana.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][213603] = {name = "[q4]Riendas de la grulla de montar pálida", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Y miré, y vi... ¿una grulla blanca?\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][213604] = {name = "[q4]Riendas de la grulla de montar tropical", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Los habitantes nativos del Bosque de Jade usan sus colores para camuflarse.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][213605] = {name = "[q4]Riendas de grulla de montar rosa", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Esta ave brillante y colorida suele confundirse con un flamenco o un marabú.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][213606] = {name = "[q4]Riendas de la grulla de montar plateada", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Esta ave tan alta es una de las grullas más agraciadas y elegantes, un poco más que la grulla de bronce, pero no tanto como la grulla dorada.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][213607] = {name = "[q4]Riendas de grulla de montar lujosa", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Un ave majestuosa, pero bastante quisquillosa con la comida.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][213608] = {name = "[q4]Riendas de cabra de montar nevada", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. La montura cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Las cabras montesas de la Cima Kun-Lai son famosas por escalar las cumbres más altas en busca de frijoles de kafa y sal para lamer.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][213609] = {name = "[q4]Riendas de cabrita de montar roja", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. La montura cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Lo que a esta cabra la falta en tamaño, le sobra en tenacidad.\"\nEvento de mundo:\nMists of Pandaria: Remix"}
MultiLanguageItemData['mx'][213610] = {name = "[q3]Polvo cristalino", additional_info = "Material de profesión\n[q]\"Polvo fino y mágico hecho de fragmentos cristalizados de una hierba o mena cristalina. Se puede comprar y vender en la casa de subastas.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213611] = {name = "[q3]Muestra retorcida", additional_info = "Material de profesión\n[q]\"Una muestra pequeña y retorcida de biomasa que se puede encontrar dentro de una hierba alterada o una mena sollozante. Se puede comprar y vender en la casa de subastas.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213612] = {name = "[q3]Esporas viridiscentes", additional_info = "Material de profesión\n[q]\"Un cúmulo de esporas rebosante de energía vital. Lo obtienen jugadores con habilidad en herboristería. Se puede comprar y vender en la casa de subastas.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213613] = {name = "[q3]Residuo de línea ley", additional_info = "Material de profesión\n[q]\"Una sustancia que contiene ciertos indicios de energía arcana remanente. Adquirida por jugadores con habilidad en herboristería. Se puede comprar y vender en la casa de subastas.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][213621] = {name = "[q4]Riendas del pterrordáctilo jade", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. La montura cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Esta montura, la favorita de los zandalari, canta muy bien, o eso piensa.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][213622] = {name = "[q4]Riendas de pterrorala nocturno", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. La montura cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Los eruditos interpretan el chirrido infernal de esta criatura como \"¡témanme, soy la noche!\"\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][213623] = {name = "[q4]Riendas de vociferador de cielos sangriento", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. La montura cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Este dinosaurio aún alberga la furia de sus ancestros durante la invasión zandalari.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][213624] = {name = "[q4]Gigante de cobalto", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. La montura cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Lo que comenzó siendo una máquina minera y maderera que se podía montar se convirtió en caos cuando los ingenieros se preguntaron si podían hacer que fuera más genial.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][213625] = {name = "[q4]Gigante férreo vil", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. La montura cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Esta máquina de guerra fue robada de una línea temporal en la que Garrosh Grito Infernal se unió a la Legión Ardiente. No hace falta decir que esa línea temporal ya casi no existe.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][213626] = {name = "[q4]Riendas del tigre de montar del Shadopan púrpura", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. La montura cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Cuando despiertes a un tigre, usa una vara larga. Mejor aún, dile a un amigo que lo despierte por ti\". —Proverbio pandaren\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][213627] = {name = "[q4]Riendas de bestia mushan cueropálido", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. La montura cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"El mushan cueropálido es la más sabrosa de las bestias mushan, pero odia que se lo recuerden.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][213628] = {name = "[q4]Riendas de mushan surcarríos", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. La montura cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Los mushan son bestias voraces. Es posible domesticarlos, pero demandarán que se les dé un segundo, tercer y hasta un cuarto desayuno todos los días.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][213629] = {name = "Sombrero desinsectador", additional_info = "Objeto de misión\n[q2]Uso: Inflige 20 p. de daño de naturaleza al objetivo enemigo actual y salta a objetivos cercanos con... resultados impredecibles. También puede saltar a criaturas que no son de prueba. (8 Seg Reutilización)\n[q]\"El invento de Jenni debería eliminar a los insectos cerca de Mmarl. En teoría.\""}
