MultiLanguageItemData['mx'][215147] = {name = "[q3]Embellecimiento del iris", additional_info = "Juguete\n[q2]Uso: Concentra un haz de luz de colores a través de una gema hacia una criatura indefensa. (10 Min Reutilización)\n[q]\"El mundo ya es cruel. No tiene por qué ser feo también.\"\nPrecio de venta:"}
