MultiLanguageItemData['mx'][216624] = {name = "[q2]Marca de arrogancia", additional_info = "Gema de artilugio\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Los atacantes sufren una Marca de arrogancia que inflige daño de las sombras cada 2 s durante 10 s y se acumula hasta 5 veces.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de artilugio.\""}
MultiLanguageItemData['mx'][216625] = {name = "[q2]Golpe rápido", additional_info = "Gema de artilugio\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Tus habilidades cuerpo a cuerpo tienen un 100% de probabilidad de provocar de 4 a 7 ataques automáticos más. (Tiempo de reutilización de 10 s)\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de artilugio.\""}
MultiLanguageItemData['mx'][216626] = {name = "[q2]Matar", additional_info = "Gema de artilugio\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Cuando atacas a un enemigo que tiene menos del 10% de salud, intentarás usar Matar, lo que inflige una cantidad de daño de las sombras equivalente al 100% de tu salud máxima.\n\n Solo intentarás Matar a un enemigo una vez.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de artilugio.\""}
MultiLanguageItemData['mx'][216627] = {name = "[q2]Escudo de maestro manitas", additional_info = "Gema de artilugio\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Otorga un escudo que absorbe una cantidad de daño equivalente a un 15% de tu salud total.\n\n Este escudo se regenerará luego de no recibir daño durante 5 s.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de artilugio.\""}
MultiLanguageItemData['mx'][216628] = {name = "[q2]Fuego de la victoria", additional_info = "Gema de artilugio\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Matar a un enemigo hace que causes una erupción que inflige daño de fuego a los enemigos y restaura salud a los aliados en un radio de 12 m.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de artilugio.\""}
MultiLanguageItemData['mx'][216629] = {name = "[q3]Traslación", additional_info = "Gema de engranaje\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Aprendes el siguiente hechizo.\n\n Traslación\nTe teletransporta 20 m hacia adelante o hasta que encuentras un obstáculo y te libera de todos los aturdimientos y ataduras.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de engranaje.\""}
MultiLanguageItemData['mx'][216630] = {name = "[q3]Salto heroico", additional_info = "Gema de engranaje\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Aprendes el siguiente hechizo.\n\n Salto heroico\nSalta por los aires hacia una ubicación objetivo y azota el suelo con fuerza destructiva, lo que inflige ([23.5% of Spell Power] + [23.5% of Attack Power]) p. de daño físico a todos los enemigos en un radio de 8 m.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de engranaje.\""}
MultiLanguageItemData['mx'][216631] = {name = "[q3]Rodar", additional_info = "Gema de engranaje\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Aprendes el siguiente hechizo.\n\n Rodar\nRuedas una corta distancia.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de engranaje.\""}
MultiLanguageItemData['mx'][216632] = {name = "[q3]Sprint", additional_info = "Gema de engranaje\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Aprendes el siguiente hechizo.\n\n Sprint\nAumenta un 70% tu velocidad de movimiento durante 8 s.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de engranaje.\""}
