MultiLanguageItemData['mx'][216647] = {name = "[q2]Granizada", additional_info = "Gema de artilugio\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Cada 3 s, genera una carga de Granizada. Al llegar a 10 acumulaciones, provoca una caída de granizo sobre los enemigos en un radio de 50 m. Cada impacto inflige daño de escarcha y aplica Frío entumecedor.\n\n Frío entumecedor\nReduce un 30% la velocidad de movimiento y reduce un 10% el daño infligido. Atacar elimina una acumulación de Frío entumecedor.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de artilugio.\""}
MultiLanguageItemData['mx'][216648] = {name = "[q2]Frente frío", additional_info = "Gema de artilugio\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Tus habilidades tienen una probabilidad de otorgar a un máximo de 5 aliados un escudo que absorbe una cantidad de daño que se reparte de forma equitativa, y aplica Frío entumecedor a todos los enemigos que estén en un radio de 50 m.\n\n Frío entumecedor\nReduce un 30% la velocidad de movimiento y reduce un 10% el daño infligido. Atacar elimina una acumulación de Frío entumecedor.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de artilugio.\""}
MultiLanguageItemData['mx'][216649] = {name = "[q2]Quebradizo", additional_info = "Gema de artilugio\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Tus habilidades aplican Quebradizo a los enemigos, que guarda un 10% del daño que infliges. Cuando un enemigo quebradizo muere, explota e inflige daño de escarcha a los enemigos en un radio de 12 m, dividido equitativamente.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de artilugio.\""}
MultiLanguageItemData['mx'][216650] = {name = "[q2]Recuerdo de venganza", additional_info = "Gema de artilugio\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Cada 10 s, obtienes un 1% de [Primary Stat] por cada 5% de salud que perdiste.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de artilugio.\""}
MultiLanguageItemData['mx'][216651] = {name = "[q2]Luz abrasadora", additional_info = "Gema de artilugio\nSe liga al recogerlo\nÚnico\n[q2]Equipar: 10% de tu sanación se acumula en los aliados como Luz abrasadora. Después de 3 s, Luz abrasadora se consume para sanar a tu aliado e infligir daño sagrado a todos los enemigos en un radio de 12 m.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de artilugio.\""}
