MultiLanguageItemData['mx'][216671] = {name = "[q4]Orbe atronador", additional_info = "Gema meta\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Aprendes el siguiente hechizo.\n\n Orbe atronador\nTe transformas en un orbe atronador que inflige daño de naturaleza a los enemigos en un radio de 30 m durante 4 s. Mientras eres un orbe atronador, el daño recibido se reduce un 50%, la velocidad de movimiento se reduce un 70%, y eres inmune a los efectos de pérdida de control.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura meta.\""}
MultiLanguageItemData['mx'][216672] = {name = "La emboscada", additional_info = "Consumible\n[q2]Uso: Te disfrazas como un simple seto. Tú y tus aliados son invisibles cuando están disfrazados.\n\n Tu combo básico se reemplaza con Setazo, que aturde a tu objetivo actual.\nPrecio de venta:"}
