MultiLanguageItemData['mx'][216882] = {name = "Registro 467-21-5", additional_info = "Objeto de misión\n[q]\"Anotación: Se observa una expansión de micelio a un ritmo alarmante que comienza a infiltrarse en la vegetación lindante. Los fungálidos demuestran tener una alta capacidad de respuesta a los estímulos ambientales, lo que exhibe un potencial cambio en su comportamiento ecológico.\"\n[q2]<Click derecho para leer>"}
MultiLanguageItemData['mx'][216888] = {name = "Registro 652-12-3", additional_info = "Objeto de misión\n[q]\"Anotación: Los fungálidos demuestran interacciones micorrizales agresivas, lo que causa que superen en competencia a las especies fúngicas cercanas. El crecimiento acelerado causa preocupación sobre los posibles desequilibrios ecológicos que podría haber en la zona afectada.\"\n[q2]<Click derecho para leer>"}
MultiLanguageItemData['mx'][216889] = {name = "Registro 893-03-9", additional_info = "Objeto de misión\n[q]\"Observación: Los fungálidos ahora se avanzan más allá del sitio de estudio inicial. Invasión micelial agresiva observada en hábitats inesperados. Investigación urgente necesaria para evaluar el impacto ecológico mayor de este nuevo comportamiento (...)\"\n[q2]<Click derecho para leer>"}
