MultiLanguageItemData['mx'][217605] = {name = "Pergamino de intelecto intemporal", additional_info = "[q2]Uso: Imbuye al objetivo con luminosidad y aumenta su intelecto un 4% durante 1 h.\n\n Si el objetivo está en tu grupo o tu banda, también afectará a todos los miembros del grupo o banda.\nRequiere nivel 10 - 70 ( 70)"}
MultiLanguageItemData['mx'][217606] = {name = "Pergamino de entereza intemporal", additional_info = "[q2]Uso: Imbuye al objetivo de vitalidad y aumenta un 4% su aguante durante 1 h.\n\n Si el objetivo está en tu grupo o banda, afectará a todos los miembros del grupo o la banda.\nRequiere nivel 10 - 70 ( 70)"}
MultiLanguageItemData['mx'][217607] = {name = "Pergamino de lo salvaje intemporal", additional_info = "[q2]Uso: Infunde a un objetivo aliado con el poder de lo salvaje para aumentar un 2% su versatilidad durante 1 h.\n\n Si el objetivo está en tu grupo o banda, el efecto también se aplica a todos los miembros del grupo o de la banda.\nRequiere nivel 10 - 70 ( 70)"}
MultiLanguageItemData['mx'][217608] = {name = "Pergamino de grito de batalla intemporal", additional_info = "[q2]Uso: Aumenta un 4% durante 1 h el poder de ataque de toda la banda y de todos los miembros del grupo en un radio de 100 metros.\nRequiere nivel 10 - 70 ( 70)"}
MultiLanguageItemData['mx'][217610] = {name = "Gema de recuerdos terránea", additional_info = "Objeto de misión\nÚnico\n[q]\"Esta gema de corte cuadrado es pesada para su tamaño y emite un resplandor tenue. Este alijo con forma de gema, un trabajo de ingeniería diseñado para la programación y los recuerdos terráneos, se puede remover y cargar a los Archivos terráneos.\""}
MultiLanguageItemData['mx'][217612] = {name = "[q4]Collar de bestia sombría de Zovaal", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. La montura cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"¿Me recompensarán por mi buena conducta?\", el alma le preguntó a Zovaal. \"No sé de qué hablas. Me dijeron que fuiste de lo peor\".\nLogro:\nRegreso del más allá\nCategoría:\nCaracterísticas de expansiones"}
