MultiLanguageItemData['mx'][217894] = {name = "[q3]Secretador de feromonas nerubianas", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n[q0]Ranura de fragancia\n[q0]Ranura de fragancia\n[q2]Equipar: Tus hechizos y habilidades tienen una probabilidad de secretar feromonas diferentes a tu alrededor. Tocar estas feromonas aumentará 2051 p. tu estadística principal durante 20 s. (20s de reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][217895] = {name = "[q2]Feromona volátil", additional_info = "[q]\"Un químico extraño se arremolina en esta botella. No debe tener ningún efecto secundario duradero... ¿verdad?\""}
