MultiLanguageItemData['mx'][217897] = {name = "[q2]Feromona volátil", additional_info = "[q]\"El contenedor se agita solo debido a la sustancia extraña que contiene.\""}
MultiLanguageItemData['mx'][217898] = {name = "Plegaria de odio purgado", additional_info = "Se liga al recogerlo\nÚnico\n[q2]El siguiente ataque que reduzca tu salud por debajo del 35% activa Odio purgado .\n\nOdio purgado :\nRestaura por completo tu salud, tu vigor y los recursos de clase.\nRequiere nivel 10 - 70 ( 70)"}
MultiLanguageItemData['mx'][217899] = {name = "Plegaria de orgullo purgado", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Mientras no estás en combate, obtienes Orgullo purgado .\n\nOrgullo purgado :\nTe esfumas completamente y entras en sigilo. Está garantizado que tu siguiente ataque sea un golpe crítico.\nRequiere nivel 10 - 70 ( 70)"}
MultiLanguageItemData['mx'][217900] = {name = "Plegaria de furia purgada", additional_info = "Se liga al recogerlo\nÚnico\n[q2]La próxima vez que recibas un golpe, liberarás Furia purgada .\n\nFuria purgada :\nInflige 150000 p. de daño físico a los enemigos en un radio de 8 m y los aturde durante 3 s.\nRequiere nivel 10 - 70 ( 70)"}
MultiLanguageItemData['mx'][217901] = {name = "Tambores intemporales", additional_info = "[q2]Uso: Aumenta un 15% la celeridad de todos los miembros del grupo y de la banda. Dura 40 s.\n\n Los aliados que reciben este efecto quedan agotados y no pueden volver a beneficiarse de Ansia de sangre, Heroísmo ni ningún otro efecto similar durante 10 min. (2 Min Reutilización)\nRequiere nivel 10 - 70 ( 70)"}
MultiLanguageItemData['mx'][217902] = {name = "Vial de cronoaventurero", additional_info = "[q2]Uso: Aumenta un 1000% tu regeneración de maná durante 6 s.\n\n Reduce un 50% la velocidad de movimiento. (6 Seg Reutilización)\nRequiere nivel 10 - 70 ( 70)"}
MultiLanguageItemData['mx'][217903] = {name = "[q2]Vindicación", additional_info = "Gema de artilugio\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Un 10% de tu daño se recoge en forma de Vindicación. Cada 3 s, se consume Vindicación para sanar la cantidad consumida a un máximo de 3 aliados en un radio de 50 metros.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de artilugio.\""}
MultiLanguageItemData['mx'][217904] = {name = "Jarabe de poder de cronoaventurero", additional_info = "[q2]Uso: Restaura 30000 p. de maná y aumenta [Primary Stat] un 3% durante 30 min. (5 Min Reutilización)\nRequiere nivel 10 - 70 ( 70)\n[q]\"Puedes comprarle más unidades a Nostwin en cualquier Bazar Infinito.\""}
MultiLanguageItemData['mx'][217905] = {name = "Jarabe de salud de cronoaventurero", additional_info = "[q2]Uso: Restaura 60000 p. de salud y aumenta el aguante un 3% durante 30 min. (5 Min Reutilización)\nRequiere nivel 10 - 70 ( 70)\n[q]\"Puedes comprarle más unidades a Nostwin en cualquier Bazar Infinito.\""}
MultiLanguageItemData['mx'][217906] = {name = "Comida para draco", additional_info = "Único (3)\n[q2]Uso: Restaura por completo el vigor y otorga un aumento de velocidad de vuelo. Solo se puede usar en la dracoequitación. (15 Seg Reutilización)\nRequiere nivel 10 - 70 ( 70)"}
MultiLanguageItemData['mx'][217907] = {name = "[q2]Calor", additional_info = "Gema de artilugio\nSe liga al recogerlo\nÚnico\n[q2]Equipar: La sanación recibida aumenta un 10%. El 75% de la sanación en exceso recibida se recoge en forma de Calor. Cada 5 s, se consume Calor para sanar la cantidad consumida a un aliado herido en un radio de 50 m.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de artilugio.\""}
MultiLanguageItemData['mx'][217925] = {name = "Botella de abejas", additional_info = "Se liga al recogerlo\nÚnico (3)\n[q2]Uso: Molesta a todos los enemigos en un radio de 40 metros del destino, lo que hace que entren en combate y apliquen Rasguños durante 30 s. Solo se puede usar al aire libre.\n\n Rasguños :\nHace que un enemigo reciba un 5% de daño aumentado durante 30 s. Dañar al enemigo tiene una probabilidad de aplicar más Rasguños. (1 Min Reutilización)\nRequiere nivel 10 - 70 ( 70)\n[q]\"Zumbando de furia.\""}
MultiLanguageItemData['mx'][217926] = {name = "Botella de abejas muertas", additional_info = "[q2]Uso: Inflige 1500 p. de daño físico a los enemigos en un radio de 3 m. (1 Min Reutilización)\nRequiere nivel 10 - 70 ( 70)\n[q]\"Ups.\""}
MultiLanguageItemData['mx'][217927] = {name = "[q2]Salvador", additional_info = "Gema de artilugio\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Sanar a un aliado que tenga menos del 35% de salud otorga un escudo que absorbe un 50% de la cantidad sanada.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de artilugio.\""}
MultiLanguageItemData['mx'][217928] = {name = "Pergamino de resurrección intemporal", additional_info = "[q2]Uso: Revive a un aliado muerto con un 35% de salud y maná. No se puede lanzar mientras estás en combate. (30 Seg Reutilización)\nRequiere nivel 10 - 70 ( 70)"}
MultiLanguageItemData['mx'][217929] = {name = "Pergamino de purificación intemporal", additional_info = "[q2]Uso: Disipa todos los efectos dañinos de maldición, magia, veneno y enfermedad del aliado seleccionado. (30 Seg Reutilización)\nRequiere nivel 10 - 70 ( 70)\n[q]\"El tiempo sana todas las heridas, enfermedades, maldiciones, resacas...\""}
MultiLanguageItemData['mx'][217930] = {name = "Vale de Nostwin", additional_info = "[q2]Uso: Te regresa a un bazar infinito cercano. (15 Min Reutilización)\nRequiere nivel 10 - 70 ( 70)\n[q]\"¡Gracias por tu compra, vuelve pronto!\""}
MultiLanguageItemData['mx'][217956] = {name = "Pergamino de invocación intemporal", additional_info = "[q2]Uso: Da comienzo a un ritual que crea un portal de invocación durante 3 min. Los aliados pueden usar el portal de invocación para invocar a un miembro del grupo o banda seleccionado. (30 Seg Reutilización)\nRequiere nivel 10 - 70 ( 70)"}
MultiLanguageItemData['mx'][217957] = {name = "[q2]Liberación", additional_info = "Gema de artilugio\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Un 4% de la sanación se recoge en forma de Liberación. Si un aliado tiene menos del 50% de salud tras recibir una sanación de tu parte, se consumirá Liberación para sanar la cantidad consumida, dividida en partes iguales, a un máximo de 3 aliados en un radio de 50 m.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de artilugio.\""}
