MultiLanguageItemData['mx'][217983] = {name = "[q3]Separación", additional_info = "Gema de engranaje\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Aprendes el siguiente hechizo.\n\n Separación\nSalta hacia atrás, lo que elimina los efectos de reducción de movimiento y aumenta un 25% tu velocidad de movimiento durante 4 s.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de engranaje.\""}
MultiLanguageItemData['mx'][217985] = {name = "[q3]Grifo dorado recordado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Alianza\n[q2]Uso: Te enseña a invocar esta montura. Las capacidades de esta montura dependen de tu habilidad de equitación y de la zona en la que estés.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nYa conocido\nPrecio de venta: \n[q]\"En Ventormenta adoran a los leones, y el grifo es mitad león. Por eso estas criaturas son una constante en los viajes aéreos por toda la Alianza.\"\nVendedor:\nRememorador Amuul\nZona:\nDalaran\nCosto:\n25"}
MultiLanguageItemData['mx'][217986] = {name = "[q2]Partes de huevo \"delicioso\"", additional_info = "[q]\"¡Los chefs kóbolds de Minahonda están de acuerdo! Ningún platillo está completo sin estos huevos.\""}
MultiLanguageItemData['mx'][217987] = {name = "[q3]Jinete del viento recordado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Horda\n[q2]Uso: Te enseña a invocar esta montura. Las capacidades de esta montura dependen de tu habilidad de equitación y de la zona en la que estés.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nYa conocido\nPrecio de venta: \n[q]\"Cientos de batallas a lo largo de una docena de campañas se han librado y ganado a lomos de estas honorables criaturas.\"\nVendedor:\nRememorador Amuul\nZona:\nDalaran\nCosto:\n25"}
MultiLanguageItemData['mx'][217989] = {name = "[q3]Pionero", additional_info = "Gema de engranaje\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Aprendes el siguiente hechizo.\n\n Pionero\nAumenta tu velocidad de movimiento un 30% cuando no hayas atacado durante 3 s.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de engranaje.\""}
