MultiLanguageItemData['mx'][218106] = {name = "Trampa de rana petrocalma", additional_info = "Se liga al recogerlo\n[q2]Uso: Arroja una trampa de rana en el suelo que inflige 20 p. de daño físico a los enemigos que la pisan, y los aturde durante 6 s.\n\n Se puede usar en Estanque Petrocalmo y las áreas cercanas. (10 Seg Reutilización)"}
MultiLanguageItemData['mx'][218107] = {name = "Frasco de chispinsectos", additional_info = "Se liga al recogerlo\nÚnico (20)\n[q2]Uso: Agitar el frasco hace que los chispinsectos que hay dentro brillen levemente y emitan una luz tenue.\n\n Con esta luz puedes localizar objetos ocultos en el Estanque Petrocalmo y las áreas con magnaflamas cercanas. (15 Seg Reutilización)\n[q]\"Los pequeños bichos luminiscentes de su interior proporcionan una luz de colores extravagante.\""}
MultiLanguageItemData['mx'][218108] = {name = "[q3]Pacto oscuro", additional_info = "Gema de engranaje\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Aprendes el siguiente hechizo.\n\n Pacto oscuro\nSacrifica un 20% de tu salud actual para protegerte por un 200% de la salud sacrificada durante 20 s. Se puede utilizar mientras sufres efectos de pérdida de control.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de engranaje.\""}
MultiLanguageItemData['mx'][218109] = {name = "[q3]Avance de la muerte", additional_info = "Gema de engranaje\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Aprendes el siguiente hechizo.\n\n Avance de la muerte\nDurante 10 s, tu velocidad de movimiento aumenta un 35%, no te pueden ralentizar por debajo del 100% de la velocidad normal, y eres inmune a los efectos que te obligan a moverte y a las repulsiones.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de engranaje.\""}
MultiLanguageItemData['mx'][218110] = {name = "[q3]Forma de alma", additional_info = "Gema de engranaje\nSe liga al recogerlo\nÚnico\n[q2]Equipar: Aprendes el siguiente hechizo.\n\n Forma de alma\nTe conviertes en un vulpino durante 12 s, lo que te teletransporta hacia adelante 15 m y aumenta tu velocidad de movimiento un 50%. Puedes volver a activar Forma de alma cada cierta cantidad de segundos para teletransportarte otra vez.\nRequiere nivel 10 - 70 ( 70)\n[q]\"Encaja en una ranura de engranaje.\""}
MultiLanguageItemData['mx'][218111] = {name = "[q4]Riendas del pterrordáctilo ámbar", additional_info = "Remix: Pandaria\nSe liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura cambia de acuerdo con tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"El pterrordáctilo puede (y probablemente quiera) devorarte en segundos. ¿Te parece buena idea sentarte en su espalda?\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['mx'][218112] = {name = "[q3]Silla de playa colorida", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Colocar una silla de playa colorida. (5 Min Reutilización)\n[q]\"Después de darte un chapuzón para superar el calor veraniego, podrás relajarte bajo la combinación perfecta de estos tonos que representan la calidez del ocaso y la tranquilidad de un arcoíris.\""}
