MultiLanguageItemData['mx'][219283] = {name = "Iris de obsidiana", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Estas flores negras son duras como el vuelo por el que obtienen su nombre y crecen muy bien en entornos arduos.\""}
MultiLanguageItemData['mx'][219284] = {name = "Palillos explosivos", additional_info = "Objeto de misión\n[q2]Uso: Stuns all enemies within 5 yards of the impact, rendering them unable to move or attack for 2 s.\n Inflicts 4 Fire damage to enemies within 5 yards of the impact. (Tiempo de reutilización: 5 s)\n[q]\"Con estos explosivos los túneles kóbolds colapsan sí o sí.\""}
MultiLanguageItemData['mx'][219285] = {name = "Lirio azur", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Los pétalos de esta flor crepitan con energía arcana. Se dice que sus brotes no florecerán a menos que estén en presencia de una gran cantidad de magia.\""}
MultiLanguageItemData['mx'][219286] = {name = "[q2]Yeti de globo de nieve pateable", additional_info = "Se liga al recogerlo\n[q2]Uso: Te permite invocar yetis de globo de nieve con el juguete Caja de pateables.\n [ Ya conocido ]\n[q]\"Te enseña a invocar yetis de globo de nieve pateables.\""}
MultiLanguageItemData['mx'][219287] = {name = "Margarita tocada por el tiempo", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Cubiertas con un fino polvo de bronce, estas margaritas relucen y centellean con el sol del mediodía.\""}
MultiLanguageItemData['mx'][219288] = {name = "Flor veridiana", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Los pétalos de esta flor son frescos al tacto, como si hubieran sido recién sacados de un bosque profundo y oscuro.\""}
MultiLanguageItemData['mx'][219289] = {name = "[q2]Muñeco de nieve diminuto pateable", additional_info = "Se liga al recogerlo\n[q2]Uso: Te permite invocar muñecos de nieve diminutos con el juguete Caja de pateables.\n [ Ya conocido ]\n[q]\"Te enseña a invocar muñecos de nieve diminutos pateables.\""}
MultiLanguageItemData['mx'][219290] = {name = "Flor rubí", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Estas flores son calientes al tacto, rebosan de vida y están absolutamente cubiertas de polen. Excelente para las abejas, pero no para las narices.\""}
MultiLanguageItemData['mx'][219291] = {name = "[q2]Bebé grinch pateable", additional_info = "Se liga al recogerlo\n[q2]Uso: Te permite invocar bebés grinch con el juguete Caja de pateables.\n [ Ya conocido ]\n[q]\"Te enseña a invocar bebés grinches pateables.\""}
MultiLanguageItemData['mx'][219292] = {name = "Contrabando desconcertante", additional_info = "Objeto de misión\nÚnico (5)\n[q]\"Piezas de churumbele - No agitar.\""}
MultiLanguageItemData['mx'][219293] = {name = "Inteligencia sureki", additional_info = "Objeto de misión\nÚnico (4)\n[q]\"Un conjunto inescrutable de aromas ácridos emana de este papiro aparentemente en blanco.\""}
MultiLanguageItemData['mx'][219294] = {name = "[q3]Pluma cargada de corventoso", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+549 agilidad\n[q2]Uso: Sostiene la pluma durante [1.0][1] s para atacar con el poder de la tormenta, que se precipita sobre la ubicación del objetivo e inflige ( 1 * 124864 ) p. de daño de naturaleza dividido entre los enemigos cercanos. (1 Min, 30 Seg Reutilización)\nCompleta todos los calabozos míticos+ dentro del límite de tiempo con un nivel de piedra angular de 12 durante la temporada 2 de The War Within.\nPrecio de venta:"}
MultiLanguageItemData['mx'][219295] = {name = "[q3]Sigilo de la concordancia algari", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+549 [Agilidad o Fuerza o Intelecto]\n[q2]Equipar: Tus habilidades tienen una probabilidad de llamar a un aliado terráneo para que te ayude y te respalde en combate. (15s de reutilización)\nCompleta todos los calabozos míticos+ dentro del límite de tiempo con un nivel de piedra angular de 12 durante la temporada 2 de The War Within.\nPrecio de venta:"}
MultiLanguageItemData['mx'][219296] = {name = "[q3]Núcleo skardyn entrópico", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n[q2]Aumenta tu índice de golpe crítico + 604 p.\n[q2]Equipar: Tus hechizos pueden desestabilizar la energía del Vacío y liberar un fragmento corrupto. Recuperar un fragmento te infunde brevemente su poder, lo que aumenta 1421 p. tu intelecto durante 15 s.\nCompleta todos los calabozos míticos+ dentro del límite de tiempo con un nivel de piedra angular de 12 durante la temporada 2 de The War Within.\nPrecio de venta:"}
MultiLanguageItemData['mx'][219297] = {name = "[q3]Jarra de hidromiel cinéreo", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n[q2]Equipar: De vez en cuando compartes un trago con los aliados que te ayudan en combate, lo que les otorga 700 p. de su estadística principal durante 15 s y absorbe 19079 p. de daño. Tú también bebes un sorbo, que te otorga 377 p. de [Primary Stat] y absorbe 97936 p. de daño.\n\n Cuando tu salud cae por debajo del 50%, bebes un sorbo de emergencia. Esto solo puede ocurrir cada 1 min.\n\nVálido solo para especializaciones de tanque.\nCompleta todos los calabozos míticos+ dentro del límite de tiempo con un nivel de piedra angular de 12 durante la temporada 2 de The War Within.\n[q]\"Diluido para ser consumido por mortales menores.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][219298] = {name = "[q3]Zumbador de miel voraz", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+549 [Agilidad o Fuerza]\n[q2]Uso: Invoca a un aliado voraz, cabalga hacia el ocaso (o $443387rad1 m, lo que esté más cerca) e inflige ( 1 * 149371 ) p. de daño de fuego dividido entre todos los enemigos que te cruzas. (1 Min, 30 Seg Reutilización)\nCompleta todos los calabozos míticos+ dentro del límite de tiempo con un nivel de piedra angular de 12 durante la temporada 2 de The War Within.\nPrecio de venta:"}
MultiLanguageItemData['mx'][219299] = {name = "[q3]Materializador de cerveza sinérgico", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+549 intelecto\n[q2]Equipar: Tus hechizos tienen una probabilidad de cargar el dispositivo y solicitar un barril de relleno cerca de la ubicación de tu objetivo. Cuando se daña el barril, este explota e inflige ( 1 * 84121 ) p. de daño de fuego dividido entre los enemigos cercanos.\nCompleta todos los calabozos míticos+ dentro del límite de tiempo con un nivel de piedra angular de 12 durante la temporada 2 de The War Within.\nPrecio de venta:"}
MultiLanguageItemData['mx'][219300] = {name = "[q3]Esquirla de Skarmorak", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+549 fuerza\n[q2]Uso: Agarra el fragmento con fuerza para nutrirte de la energía cristalina y aumentar 2756 p. tu maestría durante 15 s. (1 Min, 30 Seg Reutilización)\n[q2]Equipar: El fragmento atrae la energía remanente de los enemigos derrotados, lo que aumenta 58 p. tu maestría durante 15 s hasta 5 veces.\nPrecio de venta:"}
MultiLanguageItemData['mx'][219301] = {name = "[q3]Lanzador engránaran revolucionado", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n[q2]Uso: Lanza el engránaran sobrecalentado, que inflige ( 1 * 41390 ) p. de daño pirofísico a los enemigos y va perdiendo calor a medida que los atraviesa. (2 Min Reutilización)\n[q2]Equipar: Tus ataques cuerpo a cuerpo tienen una probabilidad de activar los engranajes del lanzador, lo que reduce 5 s su tiempo de reutilización y calienta tu arma. Esto hace que tu siguiente ataque inflija ( 1 * 23306 ) p. más de daño de fuego.\nPrecio de venta:"}
MultiLanguageItemData['mx'][219302] = {name = "[q3]Sinfonía del desguazador cantor", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+549 intelecto\n[q2]Equipar: Tus habilidades de sanación tienen una probabilidad de atraer el metal cercano para que forme un escudo alrededor de un aliado, que absorbe 45216 p. de daño.\n\n El escudo reacciona con una explosión al fuego e inflige 4162 p. de daño de fuego a los enemigos cercanos cuando lo golpean.\nPrecio de venta:"}
MultiLanguageItemData['mx'][219303] = {name = "[q3]Crecimiento del portavoz mayor", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n[q2]Aumenta tu índice de maestría + 604 p.\nPrecio de venta:"}
MultiLanguageItemData['mx'][219304] = {name = "[q3]Silbato de cera de conductor", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+549 agilidad\n[q2]Equipar: Tus ataques tienen una probabilidad de dirigir una vagoneta kóbold hacia tu objetivo, lo que envía a toda velocidad una tropa que choca con los enemigos y les inflige ( 1 * 61010 ) p. de daño físico que se divide entre los enemigos impactados.\nCompleta todos los calabozos míticos+ dentro del límite de tiempo con un nivel de piedra angular de 12 durante la temporada 2 de The War Within.\n[q]\"El trofeo simbólico de un héroe, puesto que no es necesario invocar a los kóbolds. Los kóbolds añoran las Catacumbas.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][219305] = {name = "[q3]Cera grabada con llamarakon", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+549 intelecto\n[q2]Equipar: Tus hechizos tienen una probabilidad de imbuir la cera, lo que hace que se convierta en una vela ardiente durante 15 s. Aumenta 1292 p. tu versatilidad y aumenta 339 p. más mientras permanezcas bajo su luz.\nCompleta todos los calabozos míticos+ dentro del límite de tiempo con un nivel de piedra angular de 12 durante la temporada 2 de The War Within.\nPrecio de venta:"}
MultiLanguageItemData['mx'][219306] = {name = "[q3]Buril del Rey Vela", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+549 intelecto\n[q2]Uso: Esculpe una copia de cera de tu objetivo, que absorbe un 50% del daño recibido. La absorción calienta la cera, lo que hace que se derrita tras absorber 264398 p. de daño. (1 Min, 30 Seg Reutilización)\nCompleta todos los calabozos míticos+ dentro del límite de tiempo con un nivel de piedra angular de 12 durante la temporada 2 de The War Within.\nPrecio de venta:"}
MultiLanguageItemData['mx'][219307] = {name = "[q3]Remanente de oscuridad", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n[q2]Equipar: Tus habilidades tienen una probabilidad de llamar a la oscuridad, lo que aumenta tu [Primary Stat] 281 p., hasta un máximo de ( 281 * 5) p.\n\n Al alcanzar la potencia máxima, la oscuridad se libera e inflige ( 1 * 35879 * 15 / 3) p. de daño de las sombras que se divide entre los enemigos cercanos durante 15 s para luego desvanecerse en el remanente.\nCompleta todos los calabozos míticos+ dentro del límite de tiempo con un nivel de piedra angular de 12 durante la temporada 2 de The War Within.\nPrecio de venta:"}
MultiLanguageItemData['mx'][219308] = {name = "[q3]Sello del Priorato", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+549 [Agilidad o Fuerza o Intelecto]\n[q2]Uso: Levanta tu sello a la luz y aumenta 2756 p. tu estadística secundaria más alta durante 20 s. Tu acto inspira a los miembros de tu grupo que tengan un sello, lo que les otorga 73 p. de la misma estadística durante 20 s. (2 Min Reutilización)\nCompleta todos los calabozos míticos+ dentro del límite de tiempo con un nivel de piedra angular de 12 durante la temporada 2 de The War Within.\nPrecio de venta:"}
MultiLanguageItemData['mx'][219309] = {name = "[q3]Tomo de devoción de la Luz", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n[q2]Equipar: Avanzas hasta los 50 Versos de la resiliencia interior y lees a medida que te atacan.\n Resiliencia interior aumenta 1438 p. tu armadura y otorga a tus ataques una probabilidad de invocar un resguardo que absorbe 67723 p. de daño mágico. Cuando terminas, pasas los pasajes hasta llegar a otro capítulo.\n\nVálido solo para especializaciones de tanque. (500ms de reutilización)\n[q2]Uso: Examina los pasajes del tomo con un aumento de Resplandor . (1 Min, 30 Seg Reutilización)\nCompleta todos los calabozos míticos+ dentro del límite de tiempo con un nivel de piedra angular de 12 durante la temporada 2 de The War Within.\nPrecio de venta:"}
MultiLanguageItemData['mx'][219310] = {name = "[q3]Cristal luminoso llameante", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+549 intelecto\n[q2]Uso: Invoca a un engendro de luz explosivo que sacrifica su salud para desatar Ráfagas de luz, e inflige 57024 p. de daño sagrado dividido entre los enemigos cercanos cada 2 s mientras viva. (2 Min Reutilización)\nCompleta todos los calabozos míticos+ dentro del límite de tiempo con un nivel de piedra angular de 12 durante la temporada 2 de The War Within.\nPrecio de venta:"}
MultiLanguageItemData['mx'][219311] = {name = "[q3]Piedra del pacto del vacío", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+549 fuerza\n[q2]Equipar: Tus ataques tienen una probabilidad de invocar el pacto, lo que causa una explosión que inflige ( 1 * 35361 ) p. de daño de las sombras repartidos entre los enemigos cercanos. También aumenta 377 p. tu celeridad durante 10 s.\n\n Si mueres, el pacto se rompe y se produce una explosión violenta.\nPrecio de venta:"}
MultiLanguageItemData['mx'][219312] = {name = "[q3]Cristal de potenciamiento de Anub'ikkaj", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+549 [Agilidad o Intelecto]\n[q2]Equipar: Tus hechizos y habilidades tienen una probabilidad de liberar un potenciador emergente del cristal, lo que aumenta 1392 p. una estadística secundaria aleatoria durante 20 s.\nPrecio de venta:"}
MultiLanguageItemData['mx'][219313] = {name = "[q3]Campanada de Mereldar", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+549 intelecto\n[q2]Uso: Libera una descarga de luz sagrada sobre el objetivo que inflige ( 1 * 53941 ) p. de daño sagrado. Los siguientes 5 aliados que ataquen al objetivo recibirán la Bendición de Mereldar, que aumenta 658 p. su versatilidad durante 10 s. (1 Min, 30 Seg Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][219314] = {name = "[q3]Sacocría ara-kara", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n[q2]Aumenta tu índice de celeridad + 604 p.\n[q2]Equipar: Tus habilidades tienen una probabilidad de agitar el saco y liberar un huevo que te otorga 213 p. de [Primary Stat]. Cada huevo eclosiona después de 1 min. La nueva cría ataca a tu siguiente objetivo y le inflige ( 1 * 1598 * 8 / 1) p. de daño de naturaleza durante 8 s. (100ms de reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][219315] = {name = "[q3]Módulo refractor de agresión", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+549 [Agilidad o Fuerza]\n[q2]Equipar: Tus habilidades de provocación activan la energía refractante del módulo, lo que te protege de un 50% del daño recibido, hasta 301603 p. Esto solo puede ocurrir una vez cada 1 min.\n\nVálido solo para especializaciones de tanque. (1m de reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][219316] = {name = "[q3]Glándula de enjambre implacable", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+549 [Agilidad o Fuerza]\n[q2]Equipar: La glándula libera feromonas que atraen a un Enjambre implacable de insectos que te rodean. Cuando recibes daño, tienes una alta probabilidad de contraatacar a los atacantes, lo que inflige ( 2726 * 6 / 1) p. de daño de naturaleza durante 6 s y reduce 3781 p. el daño que recibes.\nPrecio de venta:"}
MultiLanguageItemData['mx'][219317] = {name = "[q3]Edicto del cosechador", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+549 [Agilidad o Intelecto]\n[q2]Equipar: Tus habilidades y hechizos que infligen daño tienen una probabilidad de enviar un orbe de sangre negra volátil que flota hacia tu objetivo y que, al impactar, explota e inflige ( 1 * 55918 ) p. de daño de las sombras repartidos entre todos los enemigos cercanos. Si interceptas el orbe, podrás desviar su poder y aumentar 1653 p. tu maestría durante 15 s.\nPrecio de venta:"}
MultiLanguageItemData['mx'][219318] = {name = "[q3]Laringe del orador opresivo", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n[q2]Equipar: Tus ataques tienen una probabilidad de avivar la laringe, lo que permite que sus susurros oscuros te afecten. Cada susurro fluye por tu mente durante 30 s, lo que te otorga 198 p. de fuerza.\n[q2]Uso: Ondea la laringe en el aire para liberar un coro atormentador, que inflige ( 1 * 58370 * 3 / 1) p. de daño de las sombras durante 3 s dividido entre los enemigos cercanos. Tus susurros se unen al coro, lo que aumenta su daño antes de silenciarse. (2 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][219319] = {name = "[q3]Instrumentos de colmillos gemelos", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+549 agilidad\n[q2]Uso: Abre la faltriquera y saca la hoja de las sombras de Nx para golpear rápidamente a los enemigos que tengas delante, lo que inflige ( 1 * 23075 ) p. de daño de las sombras a todos los enemigos golpeados.\n\n Puedes usar la faltriquera hasta dos veces más durante 20 s antes de que se selle para recargar mágicamente su contenido. (2 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][219320] = {name = "[q3]Coaglam viscoso", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+549 intelecto\n[q2]Equipar: Tu sanación excesiva atrae la energía de las sombras cercanas a tu grupo, que se acumula hasta llegar a 8407 p. de sanación y restaura la salud del objetivo cuando recibe daño.\n[q2]Uso: Canaliza el poder del coaglam y concentra toda la energía de las sombras actual para escudar a tu objetivo. (1 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][219321] = {name = "[q3]Creación con cirros", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+549 intelecto\n[q2]Equipar: Tus hechizos tienen una probabilidad de inspirarte a experimentar en un aliado, lo que lo potencia de formas impredecibles durante 20 s.\nPrecio de venta:"}
