MultiLanguageItemData['mx'][221871] = {name = "[q2]Prototipo: Poción detonante de velocidad", additional_info = "Se liga al recogerlo\nÚnico: Prototipo (1)\n[q2]Uso: Lanza una poción detonante que salpica hasta 5 aliados con aumento explosivo de entre 10 y 15% de la velocidad de movimiento (según la calidad de fabricación) durante 20 s.\n\n Los enemigos atrapados en la explosión sufren 67738 p. de daño de fuego, que se reparten entre ellos.\nRequiere Ingeniería de Khaz Algar (1)\nPrecio de venta:"}
MultiLanguageItemData['mx'][221875] = {name = "[q2]Prototipo: Poción detonante de recuperación", additional_info = "Se liga al recogerlo\nÚnico: Prototipo (1)\n[q2]Uso: Lanza una poción detonante que salpica hasta 5 aliados con una infusión explosiva que aumenta la sanación entre 5 y 10% (según la calidad de fabricación) durante 12 s.\n\n Los enemigos atrapados en la explosión sufren 67738 p. de daño de fuego, que se reparten entre ellos.\nRequiere Ingeniería de Khaz Algar (1)\nPrecio de venta:"}
MultiLanguageItemData['mx'][221879] = {name = "[q2]Prototipo: Poción detonante de poder", additional_info = "Se liga al recogerlo\nÚnico: Prototipo (1)\n[q2]Uso: Lanza una poción detonante que salpica hasta 5 aliados con una infusión explosiva que aumenta ( 2196 / 5) p. su estadística principal durante 30 s.\n\n Los enemigos atrapados en la explosión sufren 67738 p. de daño de fuego, que se reparten entre ellos.\nRequiere Ingeniería de Khaz Algar (1)\nPrecio de venta:"}
MultiLanguageItemData['mx'][221903] = {name = "[q2]Prototipo: Artilugio: Taladro de entregas terráneo", additional_info = "Se liga al recogerlo\nÚnico: Prototipo (1)\n[q2]Uso: Invoca un taladro de entregas terráneo para excavar en busca de distintos potenciadores de campo de batalla.\n\n El taladro dura 28 s y solo se puede invocar en combate. Solo se puede usar en campos de batalla sin puntuar y en modo de guerra en Khaz Algar. (15 Min Reutilización)\nRequiere Ingeniería de Khaz Algar (1)\nPrecio de venta:"}
MultiLanguageItemData['mx'][221907] = {name = "[q2]Prototipo: Artilugio: Inyector de salud buscacorazones", additional_info = "Se liga al recogerlo\nÚnico: Prototipo (1)\n[q2]Uso: Te inyectas en las venas una fórmula medicinal de pirofrío que te sana instantáneamente hasta 1943637 p. con una sacudida de escarcha. Para evitar que sufras una hipotermia repentina, arderás por un 30% de la cantidad sanada.\n\n Comparte el tiempo de reutilización con las pociones de sanación.\nRequiere Ingeniería de Khaz Algar (1)\nPrecio de venta:"}
MultiLanguageItemData['mx'][221944] = {name = "[q2]Prototipo: Botón rojo irresistible", additional_info = "Se liga al recogerlo\nÚnico: Prototipo (1)\n[q2]Uso: Coloca un dispositivo que puedes activar tú o un miembro del grupo o de la banda cuando se avecine una crisis. Al activarlo, intentará resucitar a todos los aliados cercanos al final del combate.\n\n Dura 1 h o hasta que se activa. Debe colocarse antes del combate.\nRequiere Ingeniería de Khaz Algar (1)\nPrecio de venta:"}
