MultiLanguageItemData['mx'][223113] = {name = "[q3]Fórmula: Encantar botas: Marcha de la caballería", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a realizar el encantamiento Marcha de la caballería.\n[q2]Alteraciones de Arathor - Accesorios acentuados\n\n Encanta un par de botas de forma permanente con la velocidad de la caballería, lo que aumenta un 0% la velocidad de montura. No se puede aplicar a objetos de nivel inferior a 350.\nRequiere Encantamiento de Khaz Algar (25)\nPrecio de venta:"}
MultiLanguageItemData['mx'][223114] = {name = "[q3]Fórmula: Encantar botas: Marcha del explorador", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a realizar el encantamiento Marcha del explorador.\n[q2]Alteraciones de Arathor - Accesorios acentuados\n\n Encanta un par de botas de forma permanente con la presteza de un explorador, lo que aumenta 175 p. tu velocidad. No se puede aplicar a objetos de nivel inferior a 350.\nRequiere Encantamiento de Khaz Algar (25)\nRequiere reconocimiento 4 con los Arathi de Cristalia.\nRequiere encantamiento de Khaz Algar y reconocimiento 4 con los Arathi de Cristalia.\nPrecio de venta:"}
MultiLanguageItemData['mx'][223115] = {name = "[q3]Fórmula: Encantar anillo: Golpe crítico radiante", additional_info = "[q2]Uso: Te enseña a realizar el encantamiento Golpe crítico radiante.\n[q2]Alteraciones de Arathor - Accesorios acentuados\n\n Encanta un anillo de forma permanente con la radiancia de Beledar para aumentar 220 p. tu golpe crítico. No se puede aplicar a objetos de nivel inferior a 350.\nRequiere Encantamiento de Khaz Algar (25)\nPrecio de venta:"}
