MultiLanguageItemData['mx'][223138] = {name = "[q3]Fórmula: Encantar capa: Canto de gracia alada", additional_info = "[q2]Uso: Te enseña a realizar el encantamiento Canto de gracia alada.\n[q2]Innovaciones nerubianas - Trivialidades terciarias\n\n Encanta una capa de forma permanente con magia ancestral que le transfiere poder, lo que otorga 380 p. de evasión y reduce un 0% el daño por caída. No se puede aplicar a objetos de nivel inferior a 350.\nRequiere Encantamiento de Khaz Algar (25)\nPrecio de venta:"}
MultiLanguageItemData['mx'][223139] = {name = "[q3]Fórmula: Encantar capa: Canto de colmillos absorbentes", additional_info = "[q2]Uso: Te enseña a realizar el encantamiento Canto de colmillos absorbentes.\n[q2]Innovaciones nerubianas - Trivialidades terciarias\n\n Encanta una capa de forma permanente con magia ancestral que le transfiere poder, lo que otorga 715 p. de robo de vida y sana 174266 p. de salud cada 5 s mientras estás fuera de combate. No se puede aplicar a objetos de nivel inferior a 350.\nRequiere Encantamiento de Khaz Algar (25)\nPrecio de venta:"}
MultiLanguageItemData['mx'][223140] = {name = "[q3]Fórmula: Encantar capa - Canto de rapidez excavadora", additional_info = "[q2]Uso: Te enseña a realizar el encantamiento Canto de rapidez excavadora.\n[q2]Innovaciones nerubianas - Trivialidades terciarias\n\n Encanta una capa de forma permanente con magia ancestral que le transfiere poder, lo que otorga 175 p. de velocidad y reduce un 0% el tiempo de reutilización de tu piedra de hogar cuando estás en Khaz Algar. No se puede aplicar a objetos de nivel inferior a 350.\nRequiere Encantamiento de Khaz Algar (25)\nPrecio de venta:"}
MultiLanguageItemData['mx'][223141] = {name = "[q3]Fórmula: Encantar anillo: Golpe crítico maldito", additional_info = "[q2]Uso: Te enseña a realizar el encantamiento Golpe crítico maldito.\n[q2]Innovaciones nerubianas - Cánticos malditos\n\n Infunde un anillo de forma permanente con un cántico maldito, lo que reduce -53 p. tu celeridad y te otorga 180 p. de golpe crítico. No se puede aplicar a objetos de nivel inferior a 350.\nRequiere Encantamiento de Khaz Algar (25)\nPrecio de venta:"}
