MultiLanguageItemData['mx'][223144] = {name = "[q4]Fórmula: Encantar arma: Autoridad de las profundidades", additional_info = "[q2]Uso: Te enseña a realizar el encantamiento Autoridad de las profundidades.\n[q2]Novedades nerubianas\n\n Encanta un arma con la Autoridad de las profundidades de forma permanente. Al dañar enemigos, puedes invocar esa autoridad, lo que les aplica Oscuridad sofocante e inflige ( 1 * 24502) p. de daño de las sombras periódicamente. La oscuridad se intensifica hasta un máximo de 3 veces. No se puede aplicar a objetos de nivel inferior a 350.\nRequiere Encantamiento de Khaz Algar (25)\nPrecio de venta:"}
MultiLanguageItemData['mx'][223145] = {name = "[q3]Marrlok", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Te enseña a invocar a este compañero.\n[q2]Haz clic derecho para invocar y retirar a este compañero.\nRequiere nivel 1 - 80 ( 80)"}
MultiLanguageItemData['mx'][223146] = {name = "[q3]Cartera de semillas natormento", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Planta una de las semillas. (1 Min Reutilización)\n[q]\"El poder de una tormenta sirve tanto para la creación como para la destrucción.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][223153] = {name = "[q4]Riendas de la abeja de hidromiel planeadora", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Esta humilde abeja sueña con cielos abiertos. La presencia de un aventurero que la acompañe no es más que un accesorio para ella.\"\nVendedor:\nCendvin\nZona:\nLa Isla de Dorn\nCosto:\n900"}
MultiLanguageItemData['mx'][223155] = {name = "[q3]Ranchi", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a invocar a este compañero.\n[q2]Haz clic derecho para invocar y retirar a este compañero.\nRequiere nivel 1 - 80 ( 80)"}
MultiLanguageItemData['mx'][223157] = {name = "Coraza de herrero", additional_info = "Objeto de misión\n[q]\"Faerin reconoció que se trata de una pieza que perteneció a Ryton Blackholme. Es una de sus obras maestras. Las marcas sangrientas no dejan dudas del final que tuvo el herrero.\""}
MultiLanguageItemData['mx'][223158] = {name = "[q4]Cenizabeja iracunda", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"De temperamento tan ardiente como sus llamas, esta especie de cenizabejas solo puede ser domada por los que comparten su insaciable afición por la violencia.\"\nLogro:\nOferta de Ruffious\nCategoría:\nMundo"}
