MultiLanguageItemData['mx'][223956] = {name = "Receta: Todo-en-un-pincho", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a fabricar todo-en-un-pincho.\n[q2]Receta para 2 porciones. El número real de porciones varía según la habilidad en la cocina.\nRequiere Cocina de Khaz Algar (35)\nPrecio de venta:\n[q3]Todo-en-un-pincho\nSe liga al recogerlo\n[q2]Uso: Restaura ( 375000 / 5 * 20) p. de salud durante 20 s. Debes permanecer sentado mientras comes.\n\n Bien alimentado\n Si comes durante al menos 10 s, quedarás Bien alimentado y obtendrás las estadísticas equivalentes a las de una comida de Khaz Algar aleatoria.\n[q]\"¡Podría ser cualquier cosa!\"\nPrecio de venta:\nRequiere Yema coagulada"}
MultiLanguageItemData['mx'][223957] = {name = "Receta: Sorbo de proteína", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a fabricar un sorbo de proteína.\n[q2]Receta para 1 porciones. El número real de porciones varía según la habilidad en la cocina.\nRequiere Cocina de Khaz Algar (35)\nPrecio de venta:\nSorbo de proteína\n[q2]Uso: Restaura ( 375000 / 5 * 20) p. de maná durante 20 s. Debes permanecer sentado mientras bebes.\n\n Bien alimentado \nSi comes durante al menos 10 s quedarás Bien alimentado , obtendrás [ 470 * (0.7)] p. de tu estadística secundaria más baja y aumentarás tu tamaño un 1% durante 15 min.\n[q]\"Burbujeante.\"\nPrecio de venta:\nRequiere Polvo de huevo de primera (5)"}
