MultiLanguageItemData['mx'][224760] = {name = "[q3]Tembleques", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a invocar y retirar a este compañero.\n[q2]Haz clic derecho para invocar y retirar a este compañero."}
MultiLanguageItemData['mx'][224761] = {name = "[q2]Equipo de velas mechaveloz", additional_info = "Se liga al recogerlo\n[q2]Uso: Coloca una copia de cera de ti mismo en tu ubicación actual. (40 Seg Reutilización)\n[q]\"Este equipo de velas se puede usar para hacer varias velas pequeñas. O una gran escultura de cera.\""}
MultiLanguageItemData['mx'][224762] = {name = "Bota de agua de surcabismos", additional_info = "[q2]Uso: Restaura ( 375000 / 5 * 20) p. de maná durante 20 s. Debes permanecer sentado mientras bebes.\nPrecio de venta:"}
MultiLanguageItemData['mx'][224763] = {name = "[q3]Boceto: Blasfemia cúbica", additional_info = "[q2]Uso: Te enseña a fabricar una blasfemia cúbica.\n[q2]Los cortes de blasfemia cúbica de alta calidad requieren especialización en las técnicas de tallado de gemas de las cuatro gemas más preciadas de Khaz Algar. Incluso una imitación barata requiere una técnica perfecta.\nRequiere Joyería de Khaz Algar (50)\nPrecio de venta:"}
MultiLanguageItemData['mx'][224764] = {name = "Hilo de lanamusgo", additional_info = "Material de profesión\n[q]\"Hilado con lana de ovejas de la Isla de Dorn. Un hilo resistente y versátil que venden los comerciantes de sastrería.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][224765] = {name = "[q3]Ignición permaardiente", additional_info = "Se liga al recogerlo\nÚnico (10)\n[q2]Uso: Enciende la forja.\n\n Gana ingenio, fabricación múltiple e inventiva según tu especialización en la forja eterna durante 10 min.\n[q]\"Succionado de tu maestría con la forja.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][224766] = {name = "[q3]Perro fiel", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a invocar a este compañero.\n[q2]Haz clic derecho para invocar y retirar a este compañero.\nRequiere nivel 1 - 80 ( 80)"}
MultiLanguageItemData['mx'][224767] = {name = "Partes de vela gigante", additional_info = "[q]\"Esta cera debería ser útil para Dagran. Quizás él pueda escribir una buena tesis doctoral sobre los efectos de la cera en las bolsas de los aventureros.\""}
MultiLanguageItemData['mx'][224768] = {name = "[q3]Esquema del dirigible de surcabismos: Hélice montada en el ala", additional_info = "Esquema de aeronave\nSe liga al recogerlo\nÚnico\n[q2]Uso: Desbloquea esta opción de personalización para el Dirigible de surcabismos en el estrado de transformación."}
