MultiLanguageItemData['mx'][224772] = {name = "Botín de Gallywix", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nRequiere nivel 80 - 80 ( 80)\n[q]\"Estas órdenes refieren a un botín enorme que está disponible para cualquier mechaoscura que descubra al responsable de abrir el muro en Punto de Oportunidad.\""}
MultiLanguageItemData['mx'][224773] = {name = "Vela roja de Curioseadora", additional_info = "Objeto de misión\n[q]\"Una vela con cera de color rojo oscuro. No te gustaría saber cómo los kóbolds consiguieron ese color.\""}
MultiLanguageItemData['mx'][224774] = {name = "Botella de poción de Curioseadora", additional_info = "Objeto de misión\n[q]\"Esta botella de vidrio contiene un líquido resbaladizo e indeterminado.\""}
MultiLanguageItemData['mx'][224775] = {name = "Rubíes indiscutibles de Curioseadora", additional_info = "Objeto de misión\n[q]\"Un par de gemas rojas sin tallar. Parece que son de calidad moderada y es difícil determinar si son rubíes o no.\""}
MultiLanguageItemData['mx'][224777] = {name = "Emanasombras sureki", additional_info = "Objeto de misión\nÚnico\n[q]\"Los nerubianos usan estos emisores para proyectar órdenes y mensajes de sus líderes más importantes.\""}
MultiLanguageItemData['mx'][224778] = {name = "Engrandecedor de Curioseadora", additional_info = "Objeto de misión\n[q]\"El engrandecedor parece ser una herramienta para fabricar joyas terráneas, específicamente para verlas más de cerca.\""}
MultiLanguageItemData['mx'][224779] = {name = "Calavera de Alhainr", additional_info = "Objeto de misión\n[q]\"Unas hojitas y enredaderas salen de la calavera.\""}
MultiLanguageItemData['mx'][224780] = {name = "[q3]Piel de tempestad fortalecida", additional_info = "Se liga al recogerlo\n[q2]Uso: Estudia para aumentar 1 p. tu conocimiento de desuello en Khaz Algar.\n[q]\"Un pellejo particularmente resistente. No es muy confiable cuando se trata de artesanías, pero se puede estudiar para aprender un par de cosas sobre la fauna local.\""}
MultiLanguageItemData['mx'][224781] = {name = "[q4]Pelaje abisal", additional_info = "Se liga al recogerlo\n[q2]Uso: Estudia para aumentar 2 p. tu conocimiento de desuello en Khaz Algar.\n[q]\"Un pequeño mechón de pelaje con un tono púrpura profundo. No es muy útil, pero se trata de un espécimen raro y fascinante que no se encuentra muy a menudo.\""}
MultiLanguageItemData['mx'][224782] = {name = "[q3]Garfa navaja", additional_info = "Se liga al recogerlo\n[q2]Uso: Estudia para aumentar 1 p. tu conocimiento de desuello en Khaz Algar.\n[q]\"La garfa de una criatura. Es pequeña, pero extremadamente afilada. Aunque no tenga el tamaño suficiente para tener algún uso práctico, estudiarla es fascinante.\""}
MultiLanguageItemData['mx'][224783] = {name = "[q3]Cofre de galas soberano", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Coloca un cofre con ropas de la realeza para que tú y otros se prueben. (1 Hora Reutilización)\n[q]\"Solo para aquellos con el gusto más refinado.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][224784] = {name = "[q4]Alijo del pináculo", additional_info = "Se liga al recogerlo\n[q]\"Un alijo semanal que contiene materiales para mejorar equipo, oro, equipo de aventurero y más.Los cuatro primeros alijos semanales que obtengas cada semana contienen fragmentos de llave de arca.\"\n[q2]<Click derecho para abrir>"}
MultiLanguageItemData['mx'][224786] = {name = "[q2]Traje del Rey Esqueleto", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te transforma en el Rey Esqueleto. (3 Seg Reutilización)"}
MultiLanguageItemData['mx'][224791] = {name = "[q2]Conjunto del Señor dorado", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te transformas en un Señor dorado (3 Seg Reutilización)"}
MultiLanguageItemData['mx'][224792] = {name = "[q2]Conjunto de aristócrata sanguinario", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te transformas en un aristócrata sanguino (3 Seg Reutilización)"}
MultiLanguageItemData['mx'][224797] = {name = "Registro de Zirdo", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nRequiere nivel 80 - 80 ( 80)\n[q]\"El registro contiene información acerca de los envíos de sangre negra que se hicieron por Minahonda y que fueron aprobados por Tragonublo, el Príncipe mercante del cártel Bonvapor.\""}
MultiLanguageItemData['mx'][224799] = {name = "Poción de Nizrek", additional_info = "Objeto de misión\nÚnico\n[q2]Uso: Restaura la vitalidad de un aliado. (2 Seg Reutilización)\n[q]\"Un vial con líquido que brilla tenuemente.\""}
MultiLanguageItemData['mx'][224807] = {name = "[q3]Notas de desollador algari", additional_info = "Se liga al recogerlo\n[q2]Uso: Estudia para aumentar 3 p. tu conocimiento de desuello en Khaz Algar."}
MultiLanguageItemData['mx'][224808] = {name = "Mena de ópalo", additional_info = "Objeto de misión\nÚnico (20)\n[q]\"Piezas fundamentales de un rompecabezas perdido.\""}
MultiLanguageItemData['mx'][224809] = {name = "[q3]Tubería de plomero terráneo", additional_info = "Se liga al recogerlo\n[q2]Uso: Reconducir el agua a través del sistema de cañerías antiguo para despejar la obstrucción. (3 Seg Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][224810] = {name = "Elixir de gusano arbóreo", additional_info = "Objeto de misión\nÚnico\n[q]\"Hecho de gusanos comemadera. Es popular en la Ciudad de los Hilos, a pesar de que casi no se puede tomar.\""}
MultiLanguageItemData['mx'][224811] = {name = "[q3]Setas de azúcar", additional_info = "Se liga al recogerlo\nÚnico (20)\n[q2]Uso: La esencia fúngica te transforma y aumenta la celeridad un 25% durante 30 s.\n\n Se puede utilizar en Brote de la Luz y áreas de magnaflama cercanas. (30 Seg Reutilización)\nRequiere reconocimiento 12 con los Arathi de Cristalia.\n[q]\"¡A los niños les encanta buscar estos dulces!\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][224813] = {name = "[q3]Silbato para felinos enormes", additional_info = "Se liga al recogerlo\nÚnico (20)\n[q2]Uso: Invoca un gran lince de batalla para que te ayude en combate durante 5 min.\n\n Se puede usar en Brote de la Luz y en las zonas cercanas a magnaflamas. (5 Min Reutilización)\nRequiere reconocimiento 12 con los Arathi de Cristalia.\n[q]\"Los linces más grandes siempre están a un silbido de distancia.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][224814] = {name = "[q0]Botas ligadas a la tropa de aventurero", additional_info = "Temporada 1 de The War Within\nSe liga al recogerlo\nSe desbloquea al progresar en la temporada 1 de la travesía de surcabismos.\n[q]\"Contiene una pieza de equipo de aventurero 4/8 que corresponde a tu clase.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][224815] = {name = "[q3]Talismán de la Llama", additional_info = "Se liga al recogerlo\nÚnico (20)\n[q2]Uso: Te imbuyes con la llama sagrada, lo que hace que tus ataques y habilidades invoquen ocasionalmente un elemental de luz para infligir 3 p. de daño sagrado a los objetivos.\n\n Se usa en Brote de la Luz y en áreas de magnaflama cercanas.\nRequiere reconocimiento 12 con los Arathi de Cristalia.\n[q]\"El pueblo de Arathor se está llevando los pocos talismanes de la llama que quedan.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][224816] = {name = "[q0]Almanaque nerubiano", additional_info = "[q]\"Las páginas están llenas de mapas y diagramas indistinguibles. Lo único que logras reconocer es una ilustración de oleadas sísmicas que delinean un sistema de túneles.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][224817] = {name = "[q3]Notas de herborista algari", additional_info = "Se liga al recogerlo\n[q2]Uso: Estudia para aumentar 3 p. tu conocimiento de herboristería en Khaz Algar."}
MultiLanguageItemData['mx'][224818] = {name = "[q3]Notas de minero algari", additional_info = "Se liga al recogerlo\n[q2]Uso: Estudia para aumentar 3 p. tu conocimiento de minería en Khaz Algar."}
MultiLanguageItemData['mx'][224822] = {name = "[q4]Escarbar entre la chatarra", additional_info = "[q]\"Hurga en la chatarra para encontrar partes, prototipos olvidados, ¡y más!\""}
MultiLanguageItemData['mx'][224831] = {name = "[q4]Cubo de inventos infinitos (solo RPP)", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Restablece el tiempo de reutilización de ingeniería de Khaz Algar.\n\n Este objeto es solo de prueba.\nRequiere Ingeniería de Khaz Algar (1)\n[q]\"Cuenta como un churumbele, sea lo que sea.\""}
MultiLanguageItemData['mx'][224835] = {name = "[q3]Raíces de la arboleada profunda", additional_info = "Se liga al recogerlo\n[q2]Uso: Estudia para aumentar 1 p. tu conocimiento de herboristería en Khaz Algar.\n[q]\"Las raíces continúan creciendo, incluso después de haber arrancado la rosa. No sirve para nada en particular, pero estudiarlas puede resultar interesante.\""}
MultiLanguageItemData['mx'][224837] = {name = "[q3]Piqueta maldita", additional_info = "[q7]Se liga a la tropa hasta equiparse\n{Una mano} {Hacha}\n{1,180 - 2,452 p. de daño} {Velocidad 2.60}\n(698.5 p. de daño por segundo)\n+614 [Agilidad o Fuerza]\n+3.002 aguante\n[q2]Aumenta tu índice de golpe crítico + 424 p.\n[q2]Aumenta tu índice de celeridad + 170 p.\nDurabilidad 90 / 90\n[q2]Mientras este objeto esté en tus bolsas, lo tengas equipado o lo estés usando para una transfiguración, la maldición te consumirá de vez en cuando.\n[q]\"Unas runas antiguas decoran la cabeza de metal y bajan por el mango en forma de grabados tallados. Estos patrones se vuelven más erráticos a medida que se acercan a la empuñadura hasta que solo quedan unos rasguños.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][224838] = {name = "[q3]Astilla nula", additional_info = "Se liga al recogerlo\n[q2]Uso: Estudia para aumentar 1 p. tu conocimiento de minería en Khaz Algar.\n[q]\"Una astilla de piedra nula muy pequeña que irradia un aura pulsante de vacío. No es particularmente útil para las artesanías, pero estudiarla podría enseñarte más acerca de los minerales y menas algari.\""}
