MultiLanguageItemData['mx'][225241] = {name = "[q3]Artilugio reformado: Torreta de alarma", additional_info = "Módulo de artilugio\nÚnico-Equipado: Torreta de alarma (1)\nTorreta de alarma reformada\n[q2]Equipar: Insertar en una ranura de artilugio para conseguir el siguiente efecto:\n\n Torreta de alarma\nColoca una torreta de alarma en una ubicación objetivo cercana. Si un jugador enemigo entra en su radio de detección, te alertará de su presencia e intentará defender el área durante 30 s o hasta que la destruyan.\n[q]\"Reformado para utilizarse en equipamiento de Khaz Algar. Las probabilidades de éxito son equivalentes a un artilugio algari de calidad media.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][225242] = {name = "[q3]Artilugio reformado: Desplazador de planos", additional_info = "Módulo de artilugio\nÚnico-Equipado: Desplazador de planos (1)\nDesplazador de planos reformado\n[q2]Equipar: Insertar en una ranura de artilugio para conseguir el siguiente efecto:\n\n Desplazador de planos\nOtorga invisibilidad al usuario durante 14-18 s.\n[q]\"Reformado para utilizarse en equipamiento de Khaz Algar. Las probabilidades de éxito son equivalentes a un artilugio algari de calidad media.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][225243] = {name = "[q3]Artilugio reformado: Supercolision-A-Trón", additional_info = "Módulo de artilugio\nÚnico-Equipado: Supercolision-A-Trón (1)\nSupercolision-A-Trón reformado\n[q2]Equipar: Insertar en una ranura de artilugio para conseguir el siguiente efecto:\n\n Supercolision-A-Trón\nFija la mira en un objetivo enemigo distante, a un máximo de 12 al 60 m. Después de 1.5 s, si no hay obstáculos en tu camino, cargarás contra el objetivo a la velocidad del sonido. El objetivo y tú quedarán aturdidos durante 1.5 s después del impacto.\nRequiere Ingeniería de las Islas Dragón (1)\n[q]\"Reformado para utilizarse en equipamiento de Khaz Algar. Las probabilidades de éxito son equivalentes a un artilugio algari de calidad media.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][225244] = {name = "[q3]Artilugio reformado: Cohetes de llama de las sombras", additional_info = "Módulo de artilugio\nÚnico-Equipado: Cohetes de llama de las sombras (1)\nCohetes de llama de las sombras reformados\n[q2]Equipar: Insertar en una ranura de artilugio para conseguir el siguiente efecto:\n\n Cohetes de llama de las sombras\nSalta a una plancha de madera con un cohete de llamas de las sombras caótico. Nada podría salir mal, pero si así fuera, causa 31949 p. de daño de pirosombra que se reparte entre tú y los enemigos atrapados en la supuesta explosión.\n[q]\"Reformado para utilizarse en equipamiento de Khaz Algar. Las probabilidades de éxito son equivalentes a un artilugio algari de calidad media.\"\nPrecio de venta:"}
