MultiLanguageItemData['mx'][226505] = {name = "[q4]Tejegemas nerubiano", additional_info = "Se liga al recogerlo\n[q2]Uso: Agrega una ranura a un objeto de la temporada 1 de War Within que no tenga una. Se puede usar en yelmos, brazales o cinturones. No se puede usar en equipo JcJ."}
MultiLanguageItemData['mx'][226506] = {name = "[q4]Mano de Reshkigaal", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Reshkigaal esperó su momento mientras su gente intentaba usurpar al Desterrado. Intentó atacar cuando estaba distraído, pero los espías del Carcelero la habían seguido. Con su advertencia y ayuda, el Carcelero se impuso.\"\nPuesto de venta"}
MultiLanguageItemData['mx'][226507] = {name = "Telaraña exfoliante del Venenoso Dahn", additional_info = "Se liga al recogerlo\n[q2]Uso: Te friegas con veneno de arañuelo para quitar una acumulación de Marca del erradicador.\nRequiere la reputación Compinche con el General.\n[q]\"Un exfoliante para el cuerpo hecho con veneno que remueve la suciedad y las telarañas que se acumulan por las marcas del erradicador. ¡Contiene un 88% de sabores naturales!\""}
MultiLanguageItemData['mx'][226508] = {name = "Influencia del Visir", additional_info = "Se liga al recogerlo\n[q2]Uso: Has sobornado a los nerubianos adecuados.\n\n La próxima vez que los guardias vayan a echarte de la Ciudad de los Hilos, te enviarán a la Botica Real. Este efecto dura 60 minutos.\nRequiere la reputación Cómplice con el Visir.\n[q]\"Unos documentos \"oficiales\". \"Alientan\" a los guardias de la Ciudad de los Hilos a redirigirte a la Botica Real cuando te capturan.\""}
MultiLanguageItemData['mx'][226509] = {name = "Introspección del general", additional_info = "Se liga al recogerlo\n[q2]Uso: Puedes visualizar el radio de detección de los guardias en la Ciudad de los Hilos durante 10 minutos.\n\n Has aprendido mucho del general.\nRequiere la reputación Cómplice con el General.\n[q]\"Una copia de las patrullas y métodos sureki. Te permite ver el radio de detección de todos los guardias de la Ciudad de los Hilos.\""}
MultiLanguageItemData['mx'][226510] = {name = "Fachada de la Tejedora", additional_info = "Se liga al recogerlo\n[q2]Uso: Adoptas el aspecto de un nerubiano veraforma. Los guardias de la Ciudad de los Hilos tendrán un radio de detección reducido durante 1 minuto.\n\n La Tejedora es una maestra del disfraz.\nRequiere la reputación Cómplice con la Tejedora.\n[q]\"Una poción de feromonas que engaña a los guardias de la Ciudad de los Hilos y reduce enormemente su radio de detección. Es una especialidad de la Tejedora.\""}
MultiLanguageItemData['mx'][226511] = {name = "Cataplasma mutanerubiano", additional_info = "Se liga al recogerlo\n[q2]Uso: Arrojas una poción que transforma a un guardia de la Ciudad de los Hilos en algo menos amenazante durante 30 segundos.\n\n Una mezcla que tiene el sello personal del Visir.\nRequiere la reputación Compinche con el Visir.\nRequiere la reputación Compinche con la Tejedora.\n[q]\"Una poción que se puede arrojar para transformar a las víctimas en orfarañas inofensivas durante poco tiempo. Solo funciona con los guardias de la Ciudad de los Hilos.\""}
MultiLanguageItemData['mx'][226512] = {name = "Mapa del tesoro: Monumento olvidado", additional_info = "Se liga al recogerlo\nÚnico (5)\n[q2]Uso: Revela la ubicación de un monumento olvidado en tu mapa.\nRequiere la reputación Compinche con el General."}
MultiLanguageItemData['mx'][226513] = {name = "Mapa del tesoro: Excavación kaheti", additional_info = "Se liga al recogerlo\nÚnico (5)\n[q2]Uso: Revela la ubicación de una excavación kaheti en tu mapa.\nRequiere la reputación Compinche con el Visir."}
MultiLanguageItemData['mx'][226514] = {name = "Mapa del tesoro: Alijo de orfaraña", additional_info = "Se liga al recogerlo\nÚnico (5)\n[q2]Uso: Revela la ubicación de un alijo de orfaraña en tu mapa.\nRequiere la reputación Compinche con la Tejedora."}
MultiLanguageItemData['mx'][226515] = {name = "Mapa de rumor: Recompensas", additional_info = "Se liga al recogerlo\nÚnico (5)\n[q2]Uso: Revela la ubicación de un rumor de recompensa en tu mapa."}
MultiLanguageItemData['mx'][226516] = {name = "Mapa de rumor: Perturbación", additional_info = "Se liga al recogerlo\nÚnico (5)\n[q2]Uso: Revela la ubicación de un rumor de perturbación en tu mapa."}
MultiLanguageItemData['mx'][226517] = {name = "Mapa de rumor: Espionaje", additional_info = "Se liga al recogerlo\nÚnico (5)\n[q2]Uso: Revela la ubicación de un rumor de espionaje en tu mapa."}
MultiLanguageItemData['mx'][226518] = {name = "Feroescape", additional_info = "Se liga al recogerlo\n[q2]Uso: Arrojas una implosión de varias feromonas que aturde a los guardias de la Ciudad de los Hilos durante 2 segundos, lo que te permite salir del combate.\nRequiere la reputación Compinche con el Visir.\n[q]\"Arroja esta implosión de feromonas para aturdir a los enemigos y separarte del combate. Solo funciona con los guardias de la Ciudad de los Hilos.\""}
MultiLanguageItemData['mx'][226519] = {name = "[q3]Pericia del general", additional_info = "Se liga al recogerlo\nJuguete\n[q2]Uso: Puedes visualizar el radio de detección de los guardias en la Ciudad de los Hilos.\n\n Has aprendido mucho del general.\nRequiere la reputación Compinche con la Tejedora, el General o el Visir.\n[q]\"Una copia transcripta del manual de combate que estudian todos los soldados de Azj-Kahet. Cuando está activa, te permite ver el radio de detección de todos los guardias de la Ciudad de los Hilos.\""}
MultiLanguageItemData['mx'][226520] = {name = "Feromona de la reina", additional_info = "Se liga al recogerlo\n[q2]Uso: Las feromonas de la Reina.\n\n Los guardias de la Ciudad de los Hilos ya no se meterán contigo.\nRequiere la reputación Mente maestra con la Tejedora, el General o el Visir.\n[q]\"Las feromonas de la Reina. Obtenidas con discreción. Los guardias de la Ciudad de los Hilos ya no podrán detectarte.\""}
