MultiLanguageItemData['mx'][229193] = {name = "Feromona de la reina", additional_info = "Se liga al recogerlo\n[q2]Uso: Las feromonas de la Reina.\n\n Los guardias de la Ciudad de los Hilos ya no se meterán contigo.\n[q]\"Las feromonas de la reina. Obtenidas con discreción. Los guardias de la Ciudad de los Hilos ya no podrán detectarte.\""}
MultiLanguageItemData['mx'][229194] = {name = "Feromona de la reina", additional_info = "Se liga al recogerlo\n[q2]Uso: Las feromonas de la Reina.\n\n Los guardias de la Ciudad de los Hilos ya no se meterán contigo.\n[q]\"Las feromonas de la reina. Obtenidas con discreción. Los guardias de la Ciudad de los Hilos ya no podrán detectarte.\""}
MultiLanguageItemData['mx'][229195] = {name = "Feromona de la reina", additional_info = "Se liga al recogerlo\n[q2]Uso: Las feromonas de la Reina.\n\n Los guardias de la Ciudad de los Hilos ya no se meterán contigo.\n[q]\"Las feromonas de la reina. Obtenidas con discreción. Los guardias de la Ciudad de los Hilos ya no podrán detectarte.\""}
MultiLanguageItemData['mx'][229196] = {name = "Boceto de bakar", additional_info = "Los Secretos de Azeroth\nObjeto de misión\n[q]\"Algún artista aficionado debe haber dibujado esto y lo dejó aquí. Parece ser un pequeño bakar.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][229198] = {name = "As de aire", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra una mano que sale de una nube y empuña una espada rodeada por una corona.\""}
MultiLanguageItemData['mx'][229199] = {name = "Dos de aire", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra la silueta de una persona vendada haciendo equilibrio con dos vientos fuertes sobre los hombros.\""}
MultiLanguageItemData['mx'][229200] = {name = "Tres de aire", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra tres vientos tormentosos que perforan un corazón. En el fondo se ven nubes turbulentas y lluvia.\""}
MultiLanguageItemData['mx'][229201] = {name = "Cuatro de aire", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra la efigie de un caballero en posición de rezo sobre lo que parece ser su propia tumba.\""}
MultiLanguageItemData['mx'][229202] = {name = "Cinco de aire", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra a un hombre que regaña con desdén a dos figuras desmoralizadas en retirada cuyos sacos de aire han quedado en el suelo. El hombre carga otros dos sacos sobre el hombro izquierdo y tiene uno más en la mano derecha.\""}
MultiLanguageItemData['mx'][229203] = {name = "Seis de aire", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra a un remero que lleva pasajeros en su bote a la costa más lejana. La corriente es suave y la carga es ligera, por lo que no es una tarea que exceda las posibilidades del remero.\""}
MultiLanguageItemData['mx'][229204] = {name = "Siete de aire", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra a una persona que lleva cinco vientos rápidamente. Hay otros dos vientos en el suelo y un campamento en las cercanías.\""}
MultiLanguageItemData['mx'][229205] = {name = "Ocho de aire", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra a un prisionero atado y vendado, rodeado de ocho vientos turbulentos. Sin embargo, se trata de un impedimento temporal, no de ataduras irrevocables.\""}
MultiLanguageItemData['mx'][229206] = {name = "As de fuego", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra una mano que surge de una bola de fuego ardiente y empuña una varita rodeada de humo.\""}
MultiLanguageItemData['mx'][229207] = {name = "Dos de fuego", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra una figura alta que observa el mar y la costa desde una almena. Tiene una esfera en la mano derecha y un bastón ardiente en la izquierda, que apoya en la estructura. Hay otro bastón ardiente en un anillo a la derecha de la silueta.\""}
MultiLanguageItemData['mx'][229208] = {name = "Tres de fuego", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra la silueta de una persona serena y majestuosa de espalda que observa desde un acantilado a los barcos que surcan el mar. Hay tres bastones clavados en el suelo, cada uno con un farol, y la silueta apenas se apoya en uno de ellos.\""}
MultiLanguageItemData['mx'][229209] = {name = "Cuatro de fuego", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra cuatro pilares grandes en primer plano y una gran guirnalda con las llamas más puras colgando entre ellos. Dos figuras sostienen flores aromáticas, y a su lado hay un puente sobre un foso que lleva a una casona antigua.\""}
MultiLanguageItemData['mx'][229210] = {name = "Cinco de fuego", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra a un grupo de cinco jóvenes con bastones como si fueran parte de un ejercicio. Simulan estar en una guerra y tienen fuego en la mirada.\""}
MultiLanguageItemData['mx'][229211] = {name = "Seis de fuego", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra una figura a caballo adornada con una corona de laurel que blande una espada en llamas. Cinco soldados que portan espadas similares se sitúan a un lado.\""}
MultiLanguageItemData['mx'][229212] = {name = "Siete de fuego", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra una figura que se encuentra de pie en una colina escabrosa y que, decidida, sujeta una antorcha. Hay otras seis antorchas que se elevan desde abajo en dirección de la figura.\""}
MultiLanguageItemData['mx'][229213] = {name = "Ocho de fuego", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra ocho flechas llameantes que surcan los cielos y están a punto de caer. Representan algo que está cerca, que casi se puede tocar.\""}
MultiLanguageItemData['mx'][229214] = {name = "As de escarcha", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra una mano que emerge de la tierra cubierta de nieve fresca y agarra una copa llena hasta el borde de agua humeante.\""}
MultiLanguageItemData['mx'][229215] = {name = "Dos de escarcha", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra a dos jóvenes de pie en un entorno invernal que brindan con jarros hechos del hielo más puro.\""}
MultiLanguageItemData['mx'][229216] = {name = "Tres de escarcha", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra a unos juerguistas que bailan en un jardín y alzan sus copas como si estuvieran haciéndose promesas entre sí. La nieve cae ligera a su alrededor.\""}
MultiLanguageItemData['mx'][229217] = {name = "Cuatro de escarcha", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra una figura envuelta en pieles que, sentada bajo un pino, contempla tres cálices que yacen sobre la nieve ante ella. Un brazo que surge de una nube le ofrece otro cáliz. Su rostro traiciona el descontento que siente.\""}
MultiLanguageItemData['mx'][229218] = {name = "Cinco de escarcha", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra una figura misteriosa envuelta en una capa que mira de reojo tres copas volcadas sobre charcos de agua. Otras dos copas están paradas sobre pedestales de hielo detrás de la figura. En el fondo, un puente conduce a un pequeño fuerte.\""}
MultiLanguageItemData['mx'][229219] = {name = "Seis de escarcha", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra a unos niños que riegan las flores de un jardín antiguo con copas llenas de nieve derretida.\""}
MultiLanguageItemData['mx'][229220] = {name = "Siete de escarcha", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra unas extrañas visiones que emanan de siete cálices hechos del hielo más puro. Pero estas imágenes pertenecen a un espíritu fantástico.\""}
MultiLanguageItemData['mx'][229221] = {name = "Ocho de escarcha", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra una figura con un aspecto abatido que se aleja y abandona las copas de su fortuna, sus emprendimientos, sus proyectos o sus preocupaciones pasadas para entregarse al hielo envolvente.\""}
MultiLanguageItemData['mx'][229222] = {name = "As de tierra", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra una mano que surge del suelo rocoso entre una nube de polvo sujetando un disco de piedra.\""}
MultiLanguageItemData['mx'][229223] = {name = "Dos de tierra", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra a un niño bailando con un disco de piedra en cada mano. Los discos están unidos con un cordón interminable que se asemeja al número 8 invertido.\""}
MultiLanguageItemData['mx'][229224] = {name = "Tres de tierra", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra a un escultor que trabaja en un monasterio. El aprendiz ha recibido su recompensa y ahora trabaja con intensidad.\""}
MultiLanguageItemData['mx'][229225] = {name = "Cuatro de tierra", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra una figura que tiene un disco arriba de su cabeza y sujeta otro con sus manos y brazos. Además, tiene dos discos más debajo de sus pies. Se aferra a sus posesiones con fuerza.\""}
MultiLanguageItemData['mx'][229226] = {name = "Cinco de tierra", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra a dos mendigos en medio de una tormenta de polvo que pasan por una ventana iluminada por cinco discos resplandecientes de piedra.\""}
MultiLanguageItemData['mx'][229227] = {name = "Seis de tierra", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra a una persona vestida como un comerciante que pesa dinero en una balanza y lo reparte entre los más necesitados y afligidos. Es un testimonio de su propio éxito y de la bondad que guarda en su corazón.\""}
MultiLanguageItemData['mx'][229228] = {name = "Siete de tierra", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra a un adolescente apoyándose en su bastón mientras mira fijamente siete discos de piedra que están adheridos a algunas plantas a su derecha. Podría decirse que esos son tesoros y que el corazón del joven se encuentra ahí.\""}
MultiLanguageItemData['mx'][229229] = {name = "Ocho de tierra", additional_info = "Baraja de la fortuna de la Luna Negra\n[q]\"El naipe muestra a un escultor que trabaja con varias piedras que exhibe como trofeos.\""}
