MultiLanguageItemData['mx'][229418] = {name = "[q4]Riendas del Brutosaurio dorado de comerciante", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura para tres personas con los vendedores.\n[q2]Invoca y retira a tu brutosaurio dorado de comerciante.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Morten y Killia nunca se dieron cuenta del éxito que tendría su nueva asociación comercial entre las líneas de facciones hasta el día que pudieron comprar esta espectacular criatura para ayudarlos en sus viajes. Y por supuesto que iba a tener mucho oro vistoso.\"\nTienda del juego"}
MultiLanguageItemData['mx'][229419] = {name = "Escritura de Fondobarril", additional_info = "Objeto de misión\nRequiere nivel 80 - 80 ( 80)\n[q]\"La escritura de los Apartamentos Fondobarril. A Moz ya no le hará falta.\""}
MultiLanguageItemData['mx'][229420] = {name = "Orbe de ánima", additional_info = "Objeto de misión\n[q2]Uso: Lanza una pelota a tu animal amistoso.\n[q]\"Una pelota táctil de ánima. Chilla cuando la arrojas. Parece que a los animales les encanta.\""}
MultiLanguageItemData['mx'][229422] = {name = "[q7]Cofre de equipo de Minahonda", additional_info = "Temporada 2 de The War Within\n[q7]Se liga a la tropa\n[q2]Uso: Crea un objeto de calabozo ligado al alma apropiado para tu especialización de botín durante la temporada 2 de The War Within."}
MultiLanguageItemData['mx'][229423] = {name = "Analizador de ecos", additional_info = "Objeto de misión\n[q]\"Una versión en miniatura de la tecnología del cártel Om.\""}
MultiLanguageItemData['mx'][229424] = {name = "Aspiradora de ánima", additional_info = "Objeto de misión\n[q2]Uso: Succiona a las alimañas cercanas, a los vagos y a las entidades cósmicas (probablemente).\n\n Mientras se lanza, se puede caminar. (3 Seg Reutilización)\n[q]\"Aparentemente hay un portal en la parte trasera que lleva directo a K'aresh. Te han asegurado que no es peligroso. Probablemente.\""}
MultiLanguageItemData['mx'][229425] = {name = "[q2]Maza de batalla de Barbabronce", additional_info = "Cosmético\n[q7]Se liga a la tropa\n{Una mano} {Maza}\n{1 p. de daño} {Velocidad 2.60}\n(0.4 p. de daño por segundo)\n[q]\"Esta maza, que fue forjada para los reyes de Forjaz, estará vinculada al linaje de Barbabronce por toda la eternidad.\"\n[q2]Uso: Añade esta apariencia a tu colección de tropa.\nPrecio de venta:"}
