MultiLanguageItemData['mx'][230000] = {name = "Ellie", additional_info = "Objeto de misión\nRequiere nivel 80 - 80 ( 80)\n[q]\"Un peluche de elekk muy querido con el nombre de Ellie escrito en él. Las costuras han comenzado a desgastarse y sus ojos de botón están sueltos.\""}
