MultiLanguageItemData['mx'][231756] = {name = "[q4]Chispa de luz estelar", additional_info = "Temporada 3 de The War Within\nSe liga al recogerlo\nComponente de fabricación opcional\n\n[q2]Otorga la siguiente propiedad: Fija el nivel de objeto inicial entre 678 y 691 según la calidad de fabricación y lo marca como fabricado con luz estelar.\n[q]\"Este material único de creación puede ayudar a que un artículo adquiera una excelencia superior a la de cualquier habilidad mortal.\""}
MultiLanguageItemData['mx'][231757] = {name = "[q4]Chispa de luz estelar fracturada", additional_info = "Temporada 3 de The War Within\nSe liga al recogerlo\n[q2]Uso: Combina 2 chispas de luz estelar fracturadas con 250 piedras de valor para crear una chispa de luz estelar.\nMaterial de profesión\n[q]\"Un fragmento de una chispa de luz estelar que se puede reformar si se combina con otra pieza. Se obtiene principalmente con alijos semanales.\"\nPrecio de venta:"}
