MultiLanguageItemData['mx'][232375] = {name = "Pan de luna", additional_info = "[q2]Uso: Restablece ( 1128 * 30 / 5) p. de salud durante 30 s. Debes permanecer sentado mientras comes.\n[q]\"Una versión enorme de los pequeños panes en forma de luna creciente que usan los fieles de Elune para las ofrendas ritualísticas.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][232376] = {name = "Cerezas explosivas", additional_info = "[q2]Uso: Restaura ( 56250 / 5 * 20) p. de maná durante 20 s. Debes permanecer sentado mientras bebes.\n[q]\"Guardadas herméticamente durante un año y un día en un frasco con licores de alta graduación derivados de granos. No aptas para gente con poca resistencia.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][232377] = {name = "Jarabe para la tos de papá Cebatruenos", additional_info = "[q2]Uso: Este brebaje hace que quien lo beba entre en frenesí durante 5 minutos. Alcohol fuerte.\n[q]\"Un sorbo al día mantiene el cementerio en la lejanía. Se recomienda servirlo con dos ramitas de canela.\"\nPrecio de venta:"}
