MultiLanguageItemData['mx'][232944] = {name = "Carta de advertencia de etéreos", additional_info = "Objeto de misión\nÚnico\n[q]\"No te preocupes por los bots en el punto de encuentro. El último sujeto vio a un etéreo que nos estaba observando, y no era el primero. Estos bots se asegurarán de que nadie te tome por sorpresa.\""}
