MultiLanguageItemData['mx'][232979] = {name = "[q3]Jaks Parlaquija", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Contrata a este empleado de Pantoque que puede ralentizar a tus enemigos desde la parte trasera de tu Rompenucas."}
