MultiLanguageItemData['mx'][232981] = {name = "[q3]GNZ Domavientos 9000", additional_info = "Se liga al recogerlo\n[q2]Uso: Instala este motor para aumentar la velocidad máxima de tu Rompenucas G-99 a cambio de reducir la aceleración.\nRequiere reconocimiento 19 con los Cárteles de Minahonda.\n[q]\"El bloque cuenta con cilindros de 80 milímetros de diámetro y tiene 35,000 caballos de fuerza.\""}
MultiLanguageItemData['mx'][232982] = {name = "[q3]El Pozzik estándar", additional_info = "Se liga al recogerlo\n[q2]Uso: Instala este motor para aumentar la velocidad de aceleración de tu Rompenucas G-99 a cambio de reducir la velocidad máxima.\n[q]\"Cuando el Circuito del Espejismo se destruyó durante el cataclismo, Pozzik necesitó un nuevo lugar para perfeccionar su arte.Minahonda resultó ser un terreno fértil para una revolución automática.\""}
MultiLanguageItemData['mx'][232983] = {name = "[q3]Vapor", additional_info = "Se liga al recogerlo\n[q2]Uso: Instala este turbo para aumentar la velocidad de tu Rompenucas G-99. Este turbo aumenta la velocidad máxima a cambio de reducir la eficiencia.\n[q]\"Dicen que cuando se quema como combustible libera cien veces más energía que la nitro dorada.\"\nPrecio de venta:"}
