MultiLanguageItemData['mx'][232991] = {name = "[q4]Oda a la Rompeolas", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. La montura cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira el Oda a la Rompeolas.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Es un suceso poco visto en la historia que un marinero talle en el mascarón de su barco al mismísimo monstruo que lo dejó a las puertas de la muerte. Somos una gentuza malhablada y de poca monta. Solo pensar que uno de nosotros haya tenido la humildad de honrar a una criatura semejante se acerca tanto a la locura que da miedo.\"\nZona:\nIsla de las Sirenas\nLogro:\nLa isla te recuerda"}
MultiLanguageItemData['mx'][232992] = {name = "Trozos de insectos grandes", additional_info = "Objeto de misión\n[q2]Uso: Corta un trozo grande de insecto en 5 trozos más pequeños. Es una pena que Rhubarn nunca haya especificado el tamaño que debían tener. Una gran pena.\n[q]\"Una porción de carne de insecto muy sustanciosa y viscosa.\""}
MultiLanguageItemData['mx'][233006] = {name = "[q3]Contenedor de viscosidad de alta rentabilidad", additional_info = "[q]\"Esta cosa tiene un olor apestoso y chorrea. Mejor que no se te caiga.\""}
MultiLanguageItemData['mx'][233007] = {name = "[q2]Cajón de viscosidad de mediana rentabilidad", additional_info = "[q]\"No parece tan pesado, pero definitivamente resulta duro llevarlo de acá para allá. De todas formas, la carga debe continuar.\""}
MultiLanguageItemData['mx'][233008] = {name = "Caja de viscosidad de baja rentabilidad", additional_info = "[q]\"Estas pequeñas cantidades no parecen mucho, pero si las vas sumando pueden llegar a una gran cantidad.\""}
MultiLanguageItemData['mx'][233009] = {name = "Polen de pirobrote", additional_info = "Objeto de misión\n[q]\"Este polen es atípicamente cálido al tacto.\""}
MultiLanguageItemData['mx'][233013] = {name = "Galleta de carbón", additional_info = "Se liga al recogerlo\n[q2]Uso: Restaura ( 472500 / 5 * 25) p. de salud y ( 630000 / 5 * 25) p. de maná durante 25 s. Debes permanecer sentado mientras comes."}
MultiLanguageItemData['mx'][233014] = {name = "[q4]Alijo de tesoros de celebración de bronce", additional_info = "Se liga al recogerlo\n[q]\"Un alijo semanal que contiene materiales para mejorar equipo, oro y más.El primer alijo semanal que obtengas cada semana contiene una pieza de equipo de campeón de Profundidades de Roca Negra y una llave de arca restaurada. Los siguientes alijos contienen una pieza de equipo de veterano.\"\n[q2]<Click derecho para abrir>"}
MultiLanguageItemData['mx'][233018] = {name = "Recolector de esencia", additional_info = "Objeto de misión\n[q]\"Unas barras gruesas de metal rodean un crepitante núcleo violeta de energía. El recolector vibra y palpita, lo que genera una sensación eléctrica en tus brazos.\""}
