MultiLanguageItemData['mx'][233202] = {name = "[q3]G.O.L.E.M Jr.", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Toma el control del G.O.L.E.M. Jr. durante 30 min. (1 Hora Reutilización)\n[q]\"Después de que el G.O.L.E.M. enloqueciera, Pitz decidió hacer algo más pequeño, preciso e inteligente.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][233205] = {name = "[q2]Jugo de trote", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Toma un trago de la deliciosa bebida energizante\n de Ventura y Cía. Aumenta tu velocidad de movimiento un 1-60% durante 12 s.\n\n Solo se puede usar en abismos y exteriores de Khaz Algar. (1 Min Reutilización)\n[q]\"Los resultados pueden variar.\"\nPrecio de venta:"}
