MultiLanguageItemData['mx'][233240] = {name = "[q4]Loro pirata", additional_info = "[q7]Se liga a la tropa\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\n\n Esta montura puede usar Montar en compañía.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Los loros gigantes como este son una plaga en los mares del noreste, y pueden vivir hasta 2000 años. Qué maldición para tu descendencia.\"\nEvento especial:\nPlunderstorm"}
MultiLanguageItemData['mx'][233241] = {name = "[q4]Garfagarfio", additional_info = "[q7]Se liga a la tropa\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\n\n Esta montura puede usar Montar en compañía.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Garfagarfio una vez navegó con los Bucaneros Velasangre, y más adelante con los Asaltantes Aguasnegras, pero decidió marcharse para ver qué clase de tesoros podía descubrir más allá de los mares.\"\nEvento especial:\nPlunderstorm"}
MultiLanguageItemData['mx'][233242] = {name = "[q4]Plumarino real", additional_info = "[q7]Se liga a la tropa\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Loro gigante. Esta montura cambia de acuerdo con tu habilidad de equitación y tu ubicación.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Los picos filosos de estos loros pueden abrir nueces grandes con facilidad.\"\nEvento especial:\nPlunderstorm"}
MultiLanguageItemData['mx'][233243] = {name = "[q4]Semental de las mareas plateado", additional_info = "[q7]Se liga a la tropa\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura. Solo se puede usar bajo el agua.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"El brillo de las posesiones malhabidas en tu bolsillo llamaron la atención del semental de las mareas y sus escamas plateadas.\"\nEvento especial:\nPlunderstorm"}
