MultiLanguageItemData['mx'][234282] = {name = "[q2]Flamenco de jardín decorativo", additional_info = "[q2]Uso: Coloca un flamenco de jardín decorativo para crear una atmósfera de relajación adondequiera que vayas. (5 Min Reutilización)\n[q]\"Le da un toque de decoración emplumada a dondequiera que vayas.\"\nPrecio de venta:"}
