MultiLanguageItemData['mx'][235700] = {name = "[q4]Riendas del Grifo marcado por el Vacío", additional_info = "[q7]Se liga a la tropa\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar un Grifo marcado por el Vacío.\n[q2]Invoca y retira a esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Abandonados por sus domadores, los Grifos marcados por el Vacío lograron sobrevivir gracias a las sobras de comida que podían encontrar, que en gran parte estaban corrompidas por el Vacío. Ahora que el Vacío es su sustento, solo aterrizan para satisfacer sus caprichosos paladares con comida libre de corrupción que apenas recuerdan haber disfrutado tiempo atrás.\"\nBotín:\nGrifo marcado por el Vacío\nZona:\nVisión de Ventormenta (revivida)"}
MultiLanguageItemData['mx'][235701] = {name = "Kit de construcción de mecachatarrero en decadencia", additional_info = "Duración: 1 día (tiempo real)\n[q2]Uso: Crea un robot chatarra mecánico que repara equipamiento y compra casi cualquier cosa. El robot chatarra se va después de 5 min. (15 Min Reutilización)\n[q]\"Debido a la pésima calidad del empaque, los componentes de este kit pierden energía lenta pero constantemente.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][235703] = {name = "Achicante selecto de Tragonublo", additional_info = "[q2]Uso: Te hace un poco más chico. Se acumula hasta diez veces.\n[q]\"¡Encogimiento garantizado! ¡Ahora bebible!\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][235704] = {name = "Agrandante selecto de Tragonublo", additional_info = "[q2]Uso: Te hace un poco más alto. Se acumula hasta diez veces.\n[q]\"¿Cansado de que te miren desde arriba? ¡Ahora bebible!\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][235705] = {name = "[q4]Riendas del semental forjado por el Vacío", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Estas bestias, forjadas al igual que sus herraduras, han perdido su semejanza con los caballos comunes, y ahora solo exhiben una apariencia formada por energía del Vacío.\"\nBotín:\nSemental forjado por el Vacío\nZona:\nVisión de Ventormenta (revivida)"}
MultiLanguageItemData['mx'][235706] = {name = "[q4]Arnés de Madre de manada marcada por el Vacío", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Esta madre tuvo luchar contra sus domadores corruptos para salvar a sus cachorros de un destino incierto. Sin embargo, eso no fue suficiente para liberarlos del Vacío que cubre este lugar perdido. Ella les enseñó a ser bestias aún más peligrosas, y ahora acechan por Orgrimmar en busca de comida para su madre, en una competencia por sobrevivir.\"\nBotín:\nMadre de manada marcada por el Vacío\nZona:\nVisión de Orgrimmar (revivida)"}
MultiLanguageItemData['mx'][235707] = {name = "[q4]Riendas del Jinete del viento marcado por el Vacío", additional_info = "[q7]Se liga a la tropa\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar un Jinete del viento marcado por el Vacío.\n[q2]Invoca y retira a esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Cuando se liberaron las energías del Vacío, la mayoría de los jinetes del viento se volvieron salvajes. Se mataron entre sí e incluso masacraron a sus entrenadores. Los sobrevivientes se aseguraron de cerrar y trabar las puertas de su nidal. Aún se pueden ver algunos jinetes planeando por los aires, pero ninguno se atreve a volver a su mortífero terreno para ver qué quedó.\"\nBotín:\nJinete del viento marcado por el Vacío\nZona:\nVisión de Orgrimmar (revivida)"}
MultiLanguageItemData['mx'][235709] = {name = "[q4]Gusano sombrío ny'alothano", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Es una montura voladora.\n[q2]Invoca y retira a tu Gusano sombrío ny'alothano.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Estos vestigios del pasado del Imperio Negro, precursores de los gusanos abisales, han resurgido con la aparición de Ny'alotha.\"\nLogro:\nDominio de las VisionesCategoría:\nVisiones de N'Zoth revividas"}
MultiLanguageItemData['mx'][235710] = {name = "FRESCO selecto de Tragonublo", additional_info = "Se liga al recogerlo\nRazas: Goblin\n[q2]Uso: Te vuelve fresco y genial temporalmente.\n[q]\"¡Usa la ropa más fresca, come en los restaurantes más fríos y bebe las pociones más calientes!\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][235711] = {name = "[q4]Corrupción de los Aspectos", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. La montura cambia según tu habilidad en equitación y la zona en la que estés.\n[q2]Invoca y retira a Corrupción de los Aspectos. Esta montura cambia según tu habilidad en equitación y tu ubicación.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiere el logro \"Recuerdos perdurables\" y desbloquear todas las mejoras del reloj de arena de Visiones horribles.\n\n\n[q]\"Con el triunfo de N'Zoth, lo que comenzó con Galakrond llegó a su término, y debido a que los Aspectos estaban fuera del camino, la corrupción de su especie alcanzó a completarse.\"\nVendedora:\nTori\nZona:\nDornogal\nCosto:\n40000"}
MultiLanguageItemData['mx'][235712] = {name = "[q3]Pantera de cristal del Vacío", additional_info = "[q7]Se liga a la tropa\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Esta montura correrá o volará dependiendo de tu habilidad de equitación y de la ubicación.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta: \n[q]\"Si bien muchas gemas preciosas han sido corrompidas por energías del Vacío en las visiones horribles, los maestros joyeros aún pueden usarlas para crear poderosas monturas de panteras.\"\nProfesión:\nJoyería"}
MultiLanguageItemData['mx'][235713] = {name = "Arena extraña", additional_info = "Se liga al recogerlo\n[q2]Uso: Cómeme.\n[q]\"Sedimentos de un selecto de Tragonublo. Debe ser parte de la receta.\""}
