MultiLanguageItemData['mx'][238897] = {name = "[q4]Segaerizo primaveral", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"El Segaerizo primaveral exhibe toda su energía por la mañana. Pasa la mayor parte del día buscando comida o llamando a otros segaerizos.\"\nPuesto de venta"}
MultiLanguageItemData['mx'][238900] = {name = "[q4]Segaerizo veraniego", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Al Segaerizo veraniego le gusta echarse al sol o nadar en un lago cristalino. Son excelentes para buscar comida, pero hay que darles un incentivo.\"\nPuesto de venta"}
MultiLanguageItemData['mx'][238901] = {name = "[q4]Segaerizo invernal", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Los Segaerizos invernales son mayormente criaturas nocturnas. Son un poco más lentos que los demás segaerizos, pero su resistencia no tiene comparación.\"\nPuesto de venta"}
MultiLanguageItemData['mx'][238902] = {name = "[q4]Segaerizo otoñal", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Los Segaerizos otoñales se destacan en la búsqueda de comida en los meses más fríos. Gracias a su agudo sentido del olfato, son excelentes compañeros para realizar esta actividad en el bosque. Claro que también es difícil controlarlos en entornos llenos de aromas.\"\nPuesto de venta"}
MultiLanguageItemData['mx'][238903] = {name = "Cámara azerothiana apropiada", additional_info = "Objeto de misión\n[q2]Uso: Te quedas inmóvil para documentar la flora y fauna cercanas. (3 Seg Reutilización)\n[q]\"Tiene las iniciales \"W. B.\" en el dorso. Cómo la consiguió Ve'nari es un misterio.\""}
MultiLanguageItemData['mx'][238904] = {name = "Aspiradora de ánima", additional_info = "Objeto de misión\n[q2]Uso: Succiona a las alimañas cercanas, a los vagos y a las entidades cósmicas (probablemente).\n\n Mientras se lanza, se puede caminar. (3 Seg Reutilización)\n[q]\"Aparentemente hay un portal en la parte trasera que lleva directo a K'aresh. Te han asegurado que no es peligroso. Probablemente.\""}
