MultiLanguageItemData['mx'][239074] = {name = "Cebo del Vacío", additional_info = "Objeto de misión\nÚnico\n[q2]Uso: Arroja el cebo del Vacío sobre los restos de una tempestad del Vacío derrotada en la Fractura de Laacuna para atraer a Ramon'ta. (6 Seg Reutilización)\n[q]\"Estos orbes pueden contener y liberar energía del Vacío, y actúan como cebo y contenedor según la necesidad.\""}
MultiLanguageItemData['mx'][239076] = {name = "[q4]Heraldo de Sa'bak", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Los Tol'vir hablan del legendario Sa'bak, un gran crocolisco que, según se cree, apareció en el valle sagrado del Cráter de Un'Goro. Aunque pocos han visto a Sa'bak en persona, muchos creen que fue bendecido por los guardianes titánicos para que resguarde los vastos canales acuáticos de Uldum.\"\nTienda del juego"}
MultiLanguageItemData['mx'][239078] = {name = "[q3]Runa de Estrellas infinitas inferiores", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Aplica Runa de Estrellas infinitas inferiores a un yelmo.\n\n Tus hechizos y habilidades tienen una probabilidad de golpear a un enemigo cercano con una Estrella infinita, lo que inflige ( 1 * 211298) p. de daño arcano y aumenta ( 1 * 73954) p. el daño que recibe de tus Estrellas infinitas. Este efecto se acumula hasta 6 veces antes de reiniciarse.\n\n No se puede aplicar a objetos de nivel inferior a 350. Este efecto es efímero y solo funcionará durante la temporada 2 de The War Within.\nPrecio de venta:"}
MultiLanguageItemData['mx'][239080] = {name = "[q4]Runa de Estrellas infinitas superiores", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Aplica Runa de Estrellas infinitas superiores a un yelmo.\n\n Tus hechizos y habilidades tienen una probabilidad de golpear a un enemigo cercano con una Estrella infinita, lo que inflige ( 1 * 362226) p. de daño arcano y aumenta ( 1 * 126779) p. el daño que recibe de tus Estrellas infinitas. Este efecto se acumula hasta 6 veces antes de reiniciarse.\n\n No se puede aplicar a los objetos de nivel inferior a 350. Este efecto es efímero y solo funcionará durante la temporada 2 de The War Within.\nPrecio de venta:"}
MultiLanguageItemData['mx'][239082] = {name = "[q3]Bendecido de Sa'bak", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Te enseña a invocar a este compañero.\n[q2]Haz clic derecho para invocar y retirar a este compañero.\nRequiere nivel 1 - 80 ( 80)"}
MultiLanguageItemData['mx'][239084] = {name = "[q3]Runa de Herida sangrante inferior", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Aplica Runa de Herida sangrante inferior a un yelmo.\n\n Tus hechizos y habilidades que infligen daño tienen una probabilidad de hacer que tu objetivo rezume sangre, lo que inflige ( 1 * 37774 * 7 / 1) p. de daño durante 7 s.\n\n No se puede aplicar a objetos de nivel inferior a 350. Este efecto es efímero y solo funcionará durante la temporada 2 de The War Within.\nPrecio de venta:"}
MultiLanguageItemData['mx'][239086] = {name = "[q4]Runa de Herida sangrante superior", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Aplica Runa de Herida sangrante superior a un yelmo.\n\n Tus hechizos y habilidades que infligen daño tienen una probabilidad de hacer que tu objetivo rezume sangre, lo que inflige ( 1 * 64756 * 7 / 1) p. de daño durante 7 s.\n\n No se puede aplicar a objetos de nivel inferior a 350. Este efecto es efímero y solo funcionará durante la temporada 2 de The War Within.\nPrecio de venta:"}
MultiLanguageItemData['mx'][239088] = {name = "[q3]Runa de la extremidad retorcida inferior", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Aplica Runa de la extremidad retorcida inferior a un yelmo.\n\n Tus ataques tienen una probabilidad de generar un tentáculo que ataca con Tortura mental a tu objetivo, lo que le inflige ( 1 * 95085) p. de daño de las sombras por s durante 10 s.\n\n No se puede aplicar a objetos de nivel inferior a 350. Este efecto es efímero y solo funcionará durante la temporada 2 de The War Within.\nPrecio de venta:"}
MultiLanguageItemData['mx'][239090] = {name = "[q4]Runa de la extremidad retorcida superior", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Aplica Runa de la extremidad retorcida superior a un yelmo.\n\n Tus ataques tienen una probabilidad de generar un tentáculo que ataca con Tortura mental a tu objetivo e inflige ( 1 * 163002) p. de daño de las sombras por s durante 10 s.\n\n No se puede aplicar a objetos de nivel inferior a 350. Este efecto es efímero y solo funcionará durante la temporada 2 de The War Within.\nPrecio de venta:"}
MultiLanguageItemData['mx'][239093] = {name = "[q3]Runa de Ritual del Vacío inferior", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Aplica Runa de Ritual del Vacío inferior a un yelmo.\n\n Obtienes Ritual del Vacío, que otorga a tus hechizos y habilidades una probabilidad de aumentar todas las estadísticas secundarias 47 p. por s durante 20 s.\n\n No se puede aplicar a objetos de nivel inferior a 350. Este efecto es efímero y solo funcionará durante la temporada 2 de The War Within.\nPrecio de venta:"}
