MultiLanguageItemData['mx'][241636] = {name = "[q0]Collar de pluma y cristales de tormenta", additional_info = "Se liga al recogerlo\n[q]\"Una única pluma de corventoso de color azul eléctrico cuelga entre dos piezas de cristal de tormenta. Una tuerca y un tornillo pequeños y oxidados de Minahonda forman el broche.\"\nPrecio de venta:"}
