MultiLanguageItemData['mx'][247720] = {name = "[q4]Destrero escalofriante del Jinete decapitado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Cambia según tu habilidad de equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Si por el aire te deslizas, a tus enemigos harás trizas. A este destrero querrás subir si la victoria ansías conseguir.\"\nPuesto de venta"}
MultiLanguageItemData['mx'][247721] = {name = "[q4]Destrero macabro del Jinete decapitado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Cambia según tu habilidad de equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Has empleado trucos con tus enemigos más astutos. Premia a este destrero temible con el bocadillo más apetecible.\"\nPuesto de venta"}
MultiLanguageItemData['mx'][247722] = {name = "[q4]Destrero ardiente del Jinete decapitado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Cambia según tu habilidad de equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"En su corazón un fuego se enciende cuando este corcel su vuelo emprende. Ahora elévate desde el suelo y una mejor vista contemplarás del cielo.\"\nPuesto de venta"}
MultiLanguageItemData['mx'][247723] = {name = "[q4]Destrero sagrado del Jinete decapitado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Cambia según tu habilidad de equitación y la zona en la que estés.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Lo que en tu futuro espera a tus fantasmas desespera. ¿Cuánto tiempo crees aguantar si a tu corcel decides montar?\"\nPuesto de venta"}
MultiLanguageItemData['mx'][247791] = {name = "[q4]Grifo norteño adornado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Los antiguos jinetes de grifos y los altos chamanes de los Martillo Salvaje norteños a menudo vestían a sus grifos con accesorios delicados y emplumados para indicar su rango y posición.\"\nPuesto de venta"}
MultiLanguageItemData['mx'][247792] = {name = "[q4]Grifo nidal de alto chamán", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Los antiguos chamanes Martillo Salvaje que descubrieron a los grifos creían que eran espíritus elementales en forma mortal. Este encuentro dejaría una huella imborrable en el clan Martillo Salvaje durante generaciones.\"\nPuesto de venta"}
MultiLanguageItemData['mx'][247793] = {name = "[q4]Grifo de las Tierras Altas ceniplumas", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"De acuerdo a la leyenda de los Martillo Salvaje, el plumaje naranja que presentan los grifos podría ser un rasgo hereditario que reciben de su ascendencia elemental.\"\nPuesto de venta"}
MultiLanguageItemData['mx'][247794] = {name = "[q4]Guía celestial alascuas", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Desde los pies de la colina de Khaz Modan, seguimos sus alas de ascuas encendidas, como una antorcha que surca el oscuro cielo veraniego hacia el norte\". - El peregrinaje de los primeros sabios salvajes\nPuesto de venta"}
MultiLanguageItemData['mx'][247795] = {name = "[q4]Zancabrisa irascible", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Zancabrisa irascible.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Este talbuk obstinado no es fácil de montar, incluso después de conocer a su jinete. Tener precaución.\"\nPuesto de venta"}
