MultiLanguageItemData['mx'][248410] = {name = "[q4]Regalo de tecnomante", additional_info = "Se liga al recogerlo\n[q2]Uso: Agrega una ranura a un objeto de la temporada 3 de War Within que no tenga una. Se puede usar en yelmos, brazales o cinturones. No se puede usar en equipo JcJ."}
MultiLanguageItemData['mx'][248550] = {name = "[q3]Receta: Esencia umbría", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a fabricar esencia umbría.\nRequiere Alquimia de Khaz Algar (25)\nRequiere alquimia de Khaz Algar y reconocimiento 5 con la Fundación de K'aresh.\nPrecio de venta:"}
MultiLanguageItemData['mx'][248755] = {name = "[q2]Estrella en frasco", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Rompe el frasco y deja expuesto el contenido cegador que desorienta a todas las unidades aliadas y enemigas en un radio de 8 m.\n Solo puede usarse dentro de los abismos. (1 Min Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][248761] = {name = "[q4]Barrilero de la Fiesta de la Cerveza", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Es una montura voladora.\n[q2]Invoca y retira un Barrilero de la Fiesta de la Cerveza. La montura cambia de acuerdo con tu habilidad de equitación y tu ubicación.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Ten cuidado de no beber las municiones.\"\nBotín:\nCoren Cerveza Temible\nFiesta:\nFiesta de la Cerveza"}
MultiLanguageItemData['mx'][248764] = {name = "[q2]Trampa de traslación artesanal", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Coloca una trampa de traslación a tus pies. El primer enemigo que esté a menos de 2 metros de la trampa es teletransportado 10 metros hacia atrás y se ralentiza un 50% durante 2 s.\n La trampa permanece activa durante 1 min antes de desarmarse automáticamente.\n\n Solo puede usarse en abismos y en exteriores de Khaz Algar. (1 Min Reutilización)\nPrecio de venta:"}
