MultiLanguageItemData['mx'][249218] = {name = "[q3]Instrumento forjado con maná", additional_info = "Material de profesión\n[q]\"Exquisita e inescrutable, esta obra de maquinaria es extremadamente volátil. Se obtiene en raras ocasiones al derrotar al tejeforjas Araz en la Forja de Maná Omega. Se puede comprar y vender en la casa de subastas.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][249235] = {name = "[q4]Bolsa sin fondo de entropía", additional_info = "Se liga al recogerlo\n[q2]Uso: Saca un anillo de entropía de su interior. Y otro más, y otro más..."}
MultiLanguageItemData['mx'][249417] = {name = "Lanzallamas", additional_info = "Objeto de misión\n[q2]Uso: El fuego del negociante arde simultáneamente en múltiples espectros de energía. (10 Seg Reutilización)\n[q]\"A veces, el fuego es la respuesta.\""}
